/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A62 frozen manifest; 20-lemma checkpoints are validated before publication. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('lever',{etymology:E('Lever entered English through French from Latin levare “to raise”; it names a bar used to lift a load, a means of influence, or the verb for moving something with such a bar.','lever'),contexts:[C('lever.s2','谈判策略','The union used the threat of a coordinated strike as a lever to secure safer working conditions.','工会把协调罢工的威胁作为施压手段，以争取更安全的工作条件。','The union used the threat of a coordinated strike / as a lever / to secure safer / working conditions.','lever.s2 比喻可用来影响他人或促使其采取行动的手段。','罢工威胁增加了谈判压力，推动雇主改善条件。')],mistakes:[M('The union had no lever in negotiations because it could make the employer act exactly as it wished without offering any pressure or incentive.','The union used its ability to organize workers as a lever in the negotiations.','既然能改变对方行动，就说明拥有一定影响手段。')],quiz:[Q('lever',1,1,'A physical lever is?','a bar used to lift or move a load','a written accusation','a small dictionary','a bar used to lift or move a load','lever.s1 指利用支点撬动重物的杠杆。'),Q('lever',2,2,'A political lever is?','a means of influencing decisions','a metal lifting bar only','a species of lichen','a means of influencing decisions','lever.s2 比喻影响决策的手段。'),Q('lever',3,3,'To lever a stone block is to?','move it with a bar or similar tool','publish a false statement about it','record its vocabulary','move it with a bar or similar tool','lever.s3 作动词表示用杠杆撬动。'),Q('lever',4,1,'Which tool would provide mechanical leverage?','a strong bar resting on a fulcrum','a paper lexicon','a legal liability form','a strong bar resting on a fulcrum','支点和长杆能提供杠杆作用。')]});
D('leverage',{etymology:E('Leverage is formed from lever with -age; it names the mechanical advantage of a lever and, figuratively, the power to influence someone or something.','leverage'),contexts:[C('leverage.s1','商业谈判','The small supplier gained leverage by offering a rare component that the larger manufacturer could not replace quickly.','这家小供应商提供了一种大型制造商无法迅速替代的稀有零件，因此获得了谈判筹码。','The small supplier gained leverage / by offering a rare component / that the larger manufacturer / could not replace quickly.','leverage 指杠杆作用，也比喻影响他人或局势的能力。','难以替代的零件增强了供应商的议价能力。')],mistakes:[M('The supplier had leverage because the manufacturer could immediately replace its unique part at no cost and had no need to negotiate.','The supplier had leverage because the manufacturer depended on its hard-to-replace component.','对方完全不依赖该供应商，就难以形成议价影响力。')],quiz:[Q('leverage',1,1,'A company with leverage in a negotiation has?','power to influence the other side','a written libel claim','a guaranteed exemption from every rule','power to influence the other side','leverage.s1 比喻谈判中的影响力。'),Q('leverage',2,1,'In mechanics, leverage comes from using?','a lever to move a load','a dictionary to define words','a lifeline to rescue someone','a lever to move a load','leverage 也指杠杆带来的机械优势。'),Q('leverage',3,1,'Which resource gives a seller leverage?','a product the buyer cannot easily replace','an item the buyer can obtain anywhere','an irrelevant detail','a product the buyer cannot easily replace','难以替代的产品可以提升卖方的谈判筹码。'),Q('leverage',4,1,'“Use your experience as leverage” means use it to?','gain influence or advantage','raise a stone with a bar literally','write a lexicon','gain influence or advantage','此处 leverage 指利用经验增强影响力。')]});
D('levity',{etymology:E('Levity comes from Latin levitas “lightness,” from levis “light”; it means humor or a light manner that is unsuitable for a serious occasion.','levity'),contexts:[C('levity.s1','追悼仪式','The speaker avoided levity during the memorial and kept his remarks focused on the family’s loss.','演讲者在追悼会上避免轻浮打趣，把发言重点放在家人的悲痛上。','The speaker avoided levity during the memorial / and kept his remarks / focused on / the family’s loss.','levity 指在严肃场合显得不合时宜的轻浮或玩笑态度。','追悼场合庄重，讲者刻意不插入玩笑。')],mistakes:[M('The audience criticized the speech for levity even though it contained only solemn condolences and no humor.','The audience criticized the speech for levity when the speaker joked during the memorial.','纯粹庄重的慰问不属于轻浮。')],quiz:[Q('levity',1,1,'Levity at a solemn memorial would be?','humor or lightness unsuitable to the occasion','a respectful moment of silence','a legal obligation','humor or lightness unsuitable to the occasion','levity 指严肃场合不合时宜的轻浮。'),Q('levity',2,1,'Which behavior shows levity during a serious ceremony?','making a silly joke while a family mourns','speaking quietly about the deceased','offering a sincere condolence','making a silly joke while a family mourns','哀悼时开玩笑显得轻浮。'),Q('levity',3,1,'Levity is closest to?','frivolity','liability','liberation','frivolity','frivolity 同样指轻浮。','confusable'),Q('levity',4,1,'The chair asked for less levity because the meeting concerned?','a serious safety failure','a picnic game','a comedy show','a serious safety failure','严肃安全问题不适合轻浮打趣。')]});
D('levy',{etymology:E('Levy comes through Anglo-French from lever, ultimately Latin levare “to raise”; it can name a tax or fee and the verb for officially collecting it or summoning people for service.','levy'),contexts:[C('levy.s2','地方财政','The council voted to levy a modest fee on commercial deliveries to fund repairs to the damaged bridge.','委员会投票决定向商业配送征收适度费用，用于修复受损桥梁。','The council voted to levy a modest fee / on commercial deliveries / to fund repairs / to the damaged bridge.','levy.s2 作动词，指由官方征收税款或费用。','地方机构正式决定向一类服务征收费用。')],mistakes:[M('The council levied a fee by deciding that no payment would be collected from any delivery company.','The council levied a fee by officially requiring delivery companies to pay it.','没有要求或收取付款，与 levy a fee 相反。')],quiz:[Q('levy',1,1,'A levy is?','a tax or fee collected by an authority','a phrase meaning to tell a lie','a type of flower','a tax or fee collected by an authority','levy.s1 指税款或征收费用。'),Q('levy',2,2,'To levy a tax is to?','officially demand and collect it','cancel it for every payer','use it as a lever','officially demand and collect it','levy.s2 指正式征收。'),Q('levy',3,3,'To levy troops is, in older formal usage, to?','summon people for military service','charge them a library fee','write their biographies','summon people for military service','levy.s3 可旧式地指征召人员。'),Q('levy',4,1,'Which is a local levy?','a required fee imposed by the council','a voluntary thank-you note','a dictionary of technical words','a required fee imposed by the council','官方规定必须支付的费用是 levy。')]});
D('lewis',{etymology:E('Lewis is the name of a specialized dovetailed metal fitting used to lift stone blocks; the term’s earlier personal-name origin is uncertain.','lewis'),contexts:[C('lewis.s1','石材吊装','The mason fitted the lewis into the prepared socket so the crane could raise the heavy stone block safely.','石匠把吊楔装进预制孔中，使起重机能够安全吊起沉重石块。','The mason fitted the lewis into the prepared socket / so the crane could raise / the heavy stone block / safely.','lewis 指嵌入石材燕尾槽、供起重机吊起石块的金属吊楔。','吊楔与石块槽口相扣，传递起吊力。')],mistakes:[M('The mason used a lewis to polish the stone surface, although the fitting was not inserted into a lifting socket and carried no load.','The mason inserted a lewis into the dovetailed socket so the crane could hoist the block.','lewis 用于吊装石块，不是打磨工具。')],quiz:[Q('lewis',1,1,'A lewis is used by a mason to?','attach a crane to lift a stone block','write a word in a lexicon','cut a flower petal','attach a crane to lift a stone block','lewis.s1 是石材吊装用的嵌入式金属件。'),Q('lewis',2,1,'Where is a lewis fitted?','into a dovetailed socket in masonry','around a person’s waist','inside a library card','into a dovetailed socket in masonry','吊楔装入石块上的燕尾槽。'),Q('lewis',3,1,'Which worker might use a lewis?','a stonemason preparing a block for hoisting','a lexicographer editing a dictionary','a lifeguard holding a lifeline','a stonemason preparing a block for hoisting','石匠吊装石块时会使用 lewis。'),Q('lewis',4,1,'A lewis is a specialized?','lifting fitting','written accusation','vocabulary list','lifting fitting','lewis 是起重用金属配件。')]});
D('lexical',{etymology:E('Lexical comes from Greek lexikos “of words,” from lexis “word”; it can relate to a language’s vocabulary or to dictionary work.','lexical'),contexts:[C('lexical.s1','语言学课程','The study compares lexical choices in the two translations, focusing on how each renders words for emotion.','这项研究比较两种译本的词汇选择，重点考察它们如何翻译表示情绪的词语。','The study compares lexical choices / in the two translations / focusing on how each renders / words for emotion.','lexical.s1 指与语言词汇或选词相关的。','研究比较不同译本如何选择词语。')],mistakes:[M('The linguist called punctuation spacing a lexical difference even though the two texts used exactly the same words.','The linguist called the substitution of “home” for “house” a lexical difference.','纯标点间距不是词汇选择差异。')],quiz:[Q('lexical',1,1,'A lexical choice concerns?','the words selected','the size of a stone block','the route around a track','the words selected','lexical.s1 指词汇或用词方面的。'),Q('lexical',2,2,'A lexical dictionary entry is related to?','recording words and their meanings','lifting a masonry block','collecting a tax','recording words and their meanings','lexical.s2 可指词典编纂或词典条目相关。'),Q('lexical',3,1,'Which change is lexical?','replacing “large” with “enormous”','changing a comma to a semicolon only','moving a paragraph to another page','replacing “large” with “enormous”','替换词语属于 lexical change。'),Q('lexical',4,1,'Lexical is related to the Greek idea of?','words','lifting','freedom','words','lexical 源自表示“词”的希腊语词根。','word-formation')]});
D('lexicographer',{etymology:E('Lexicographer combines lexicon, from Greek lexikon “of words,” and -grapher, “writer”; it names someone who compiles and edits dictionaries.','lexicographer'),contexts:[C('lexicographer.s1','词典编辑','The lexicographer checked older newspapers to determine when the new technical term first appeared in print.','词典编纂者查阅旧报纸，以确定这个新术语首次见于印刷品的时间。','The lexicographer checked older newspapers / to determine / when the new technical term / first appeared in print.','lexicographer 指编纂、编辑词典的人。','查证词语的用例和出现时间是词典编纂工作。')],mistakes:[M('The lexicographer compiled no word list or dictionary and worked only as a ship’s cook.','The lexicographer researched definitions and organized entries for a dictionary.','不从事词典或词条编纂的人不是 lexicographer。')],quiz:[Q('lexicographer',1,1,'A lexicographer works on?','compiling and editing dictionaries','levying local taxes','raising stone blocks','compiling and editing dictionaries','lexicographer 指词典编纂者。'),Q('lexicographer',2,1,'Which task might a lexicographer perform?','checking how a word has been used in print','repairing a lighthouse lamp','collecting rent from tenants','checking how a word has been used in print','考证词语用例是词典编纂工作。'),Q('lexicographer',3,1,'Lexicographer is related to lexicon and a word meaning?','writer','island','tax','writer','-grapher 表示书写或记录者。','word-formation'),Q('lexicographer',4,1,'A person who writes a dictionary entry is a?','lexicographer','libelous person','liar','lexicographer','词典条目由 lexicographer 编写。')]});
D('lexicon',{etymology:E('Lexicon comes from Greek lexikon, a book of words; it can mean the vocabulary of a field or a dictionary listing those terms.','lexicon'),contexts:[C('lexicon.s1','医学术语','The medical lexicon includes terms such as “ischemia,” which patients may need explained in ordinary language.','医学词汇包括“缺血”等术语，患者可能需要医生用日常语言解释。','The medical lexicon includes terms / such as “ischemia” / which patients may need / explained in ordinary language.','lexicon 指某领域使用的词汇集合，也可指收录这些词的专门词典。','术语属于医学领域的专业词汇。')],mistakes:[M('The medical lexicon contained no medical words and consisted only of a restaurant menu.','The medical lexicon included the specialized terms used by clinicians.','餐厅菜单不是医学领域的词汇集合。')],quiz:[Q('lexicon',1,1,'A field’s lexicon is?','the words used in that field','the people who own its buildings','a route marked for swimmers','the words used in that field','lexicon.s1 指某领域的词汇。'),Q('lexicon',2,1,'A lexicon can also be?','a dictionary of specialized terms','a stone-lifting fitting','a legal tax notice','a dictionary of specialized terms','lexicon 也可指专门词典。'),Q('lexicon',3,1,'A medical lexicon might include?','terms used by clinicians','only road signs','names of every lake','terms used by clinicians','医生使用的专业术语构成医学词汇。'),Q('lexicon',4,1,'Lexicon is related to the Greek word for?','word','land','light','word','lexicon 的词源与“词”有关。','word-formation')]});
D('liability',{etymology:E('Liability is formed from liable with -ity; it can mean legal responsibility or a debt and other money owed.','liability'),contexts:[C('liability.s1','企业账目','The company reported its unpaid loan as a liability on the balance sheet.','公司在资产负债表上将未偿还贷款列为负债。','The company reported its unpaid loan / as a liability / on the balance sheet.','liability 可指依法应承担的责任，也可指债务或应付款项。','未偿贷款属于企业欠下的金额。')],mistakes:[M('The accountant listed the unpaid loan as an asset and denied that the company owed any money.','The accountant listed the unpaid loan as a liability because the company had to repay it.','需要偿还的贷款是负债，不是资产。')],quiz:[Q('liability',1,1,'A legal liability is?','responsibility for an act or its consequences','a dictionary of specialized terms','a tool for lifting stone','responsibility for an act or its consequences','liability.s1 可指法律责任。'),Q('liability',2,1,'A company’s unpaid loan is a?','liability','lexicon','lily','liability','欠下且需偿还的贷款是负债。'),Q('liability',3,1,'Which item appears as a liability?','money owed to a lender','cash already received as income','a tax refund not yet requested','money owed to a lender','欠款属于负债。'),Q('liability',4,1,'Liability is the noun related to?','liable','languid','liberate','liable','liability 由 liable 派生。','word-formation')]});
D('liable',{etymology:E('Liable came through Anglo-French from a word meaning bound or obligated; it can mean legally responsible, likely to do something, or subject to a penalty or payment.','liable'),contexts:[C('liable.s2','天气风险','Because the path lies beneath a steep cliff, hikers are liable to encounter falling rocks after heavy rain.','这条小路位于陡峭悬崖下方，因此暴雨后徒步者容易遇到落石。','Because the path lies beneath a steep cliff / hikers are liable to encounter falling rocks / after heavy rain.','liable.s2 可表示可能做某事或容易受到某事影响，常与 to 连用。','地形和暴雨使落石风险增加。')],mistakes:[M('Hikers are liable to falling rocks even though the cliff is fully stabilized and no rocks can reach the path.','Hikers are liable to falling rocks because the unstable cliff overlooks the path.','没有落石可能性时，不能说徒步者容易遭遇落石。')],quiz:[Q('liable',1,1,'A person legally liable for damage is?','responsible for paying or repairing it','unconnected with the event','a dictionary editor','responsible for paying or repairing it','liable.s1 指依法承担责任。'),Q('liable',2,2,'“Children are liable to tire quickly” means they are?','likely to tire quickly','legally required to pay a fee','unable to speak','likely to tire quickly','liable.s2 可表示容易发生某事。'),Q('liable',3,3,'If an offense is liable to a fine, it is?','subject to a fine under the rules','certain to receive a reward','a type of vocabulary','subject to a fine under the rules','liable.s3 指依规则应受处罚或缴费。'),Q('liable',4,2,'Which phrase is natural?','liable to make a mistake','liable of make a mistake','liable by making a mistake','liable to make a mistake','常见搭配为 liable to do something。','collocation')]});
D('liaise',{etymology:E('Liaise is a back-formation from liaison, a French-derived word for connection; it means maintain contact and cooperate between groups or departments.','liaise'),contexts:[C('liaise.s1','项目协作','Mara will liaise with the hospital’s records team to make sure the research forms use the approved patient codes.','玛拉将与医院病历团队联络，确保研究表格使用获批的患者编码。','Mara will liaise with the hospital’s records team / to make sure / the research forms / use the approved patient codes.','liaise 指不同团队或机构之间保持联系、协调合作。','她负责联系两个团队并协调表格要求。')],mistakes:[M('Mara liaised with the records team by refusing all contact and submitting forms without checking the agreed codes.','Mara liaised with the records team by exchanging updates and agreeing on the patient codes.','拒绝沟通无法构成联络协调。')],quiz:[Q('liaise',1,1,'To liaise with another department is to?','keep in contact and cooperate with it','publish a false claim about it','charge it an official tax','keep in contact and cooperate with it','liaise 指联络并合作。'),Q('liaise',2,1,'Who is liaising?','a coordinator exchanging updates between two teams','a worker avoiding both teams','a lexicographer defining a word alone','a coordinator exchanging updates between two teams','在团队间交换信息属于 liaising。'),Q('liaise',3,1,'Which preposition usually follows liaise?','with','at','under','with','liaise 常与 with 连用。','collocation'),Q('liaise',4,1,'A liaison officer may ask an employee to?','liaise between the clinic and the research group','write a libelous post','lift a stone with a lewis','liaise between the clinic and the research group','liaise 可表示在两方之间负责沟通。')]});
D('liaison',{etymology:E('Liaison comes from French liaison, from lier “to bind”; it can mean cooperation between groups, a person who coordinates them, or in phonetics the linking of sounds across words.','liaison'),contexts:[C('liaison.s2','政府联络','The city appointed a liaison to coordinate updates between emergency services and neighborhood leaders.','市政府任命了一名联络官，负责协调应急部门与社区负责人的信息。','The city appointed a liaison / to coordinate updates / between emergency services / and neighborhood leaders.','liaison.s2 指在团体之间维持联系和协调工作的人员。','联络官负责在两个组织群体间传递信息。')],mistakes:[M('The city named a liaison to prevent all communication between emergency services and residents.','The city named a liaison to keep emergency services and residents in contact.','阻止双方沟通与联络官的职责相反。')],quiz:[Q('liaison',1,1,'A liaison between two agencies helps them?','stay in contact and coordinate','avoid all communication','raise a stone block','stay in contact and coordinate','liaison.s1 指组织间的联络合作。'),Q('liaison',2,2,'A liaison may be?','a person coordinating communication','a false written accusation','a legal debt','a person coordinating communication','liaison.s2 可指联络人或联络官。'),Q('liaison',3,3,'In phonetics, liaison is?','linking a final sound to the following word','a list of dictionary entries','a government fee','linking a final sound to the following word','liaison.s3 指语音中词间连音。'),Q('liaison',4,2,'Which employee is a liaison?','a staff member who passes updates between two teams','a worker who withholds messages from both teams','a person who compiles a dictionary','a staff member who passes updates between two teams','负责在团队间传递消息的人是联络员。')]});
D('liar',{etymology:E('Liar comes from Old English leogere, a person who tells lies; it names someone who habitually or knowingly says things that are untrue.','liar'),contexts:[C('liar.s1','证词审查','The witness called him a liar after documents showed he had knowingly changed the dates in his account.','文件显示他故意篡改陈述中的日期后，证人称他为说谎者。','The witness called him a liar / after documents showed / he had knowingly changed / the dates in his account.','liar 指说谎的人，尤其是明知不实仍作虚假陈述的人。','有文件证据表明他故意改动日期。')],mistakes:[M('The reviewer called a witness a liar solely because she gave an accurate account that matched the records.','The reviewer called the witness a liar after records proved she knowingly invented details.','陈述与记录一致且准确，不足以说明她说谎。')],quiz:[Q('liar',1,1,'A liar is someone who?','knowingly or habitually says untrue things','edits dictionary entries','owns a large library','knowingly or habitually says untrue things','liar 指说谎者。'),Q('liar',2,1,'Which person is clearly a liar in this example?','someone who invents a false alibi and knows it is false','someone who repeats a fact after checking it','someone who admits not knowing the answer','someone who invents a false alibi and knows it is false','明知不实仍编造不在场证明，属于说谎。'),Q('liar',3,1,'Liar is related to the verb?','lie','liaise','liberate','lie','liar 指 lie 的行为者。','word-formation'),Q('liar',4,1,'Calling someone a liar is a claim that the person?','has said something untrue','has a legal debt','has released a prisoner','has said something untrue','说某人是 liar，就是指其说了不实之言。')]});
D('libel',{etymology:E('Libel comes from Latin libellus, “small book,” and developed into the legal term for a false written statement that harms someone’s reputation; it is also a verb.','libel'),contexts:[C('libel.s2','媒体素养','The editor removed the unsupported written accusation before publication because it could amount to libel.','编辑在发表前删除了缺乏依据的书面指控，因为它可能构成诽谤文字。','The editor removed the unsupported written accusation / before publication / because it could amount to libel.','libel.s2 指以书面形式发表、损害他人名誉的虚假陈述。','编辑在发表前处理可能损害名誉的未证实指控。')],mistakes:[M('The editor described a verified written report as libel even though every statement was accurate and caused no false reputational harm.','The editor described the knowingly false damaging post as libel.','真实准确且无虚假名誉损害的文字不符合 libel 的核心义。')],quiz:[Q('libel',1,1,'To libel someone is to?','publish a false damaging statement about them','write a private accurate diary','charge them a lawful tax','publish a false damaging statement about them','libel.s1 作动词表示发表虚假诽谤内容。'),Q('libel',2,2,'A libel is generally a damaging false statement made?','in written or published form','only in a private unspoken thought','by collecting a fee','in written or published form','libel.s2 指书面诽谤文字。'),Q('libel',3,3,'Libel can also refer to?','the crime of publishing such a false statement','a harmless compliment','a word list','the crime of publishing such a false statement','libel.s3 指发表此类内容的犯罪。'),Q('libel',4,2,'Which statement is most likely libelous?','a published false accusation that harms a person’s reputation','a verified account of a public event','a private question about a schedule','a published false accusation that harms a person’s reputation','公开发表有损名誉的虚假指控符合 libel。')]});
D('libelous',{etymology:E('Libelous is formed from libel with the adjective suffix -ous; it describes a false written statement that damages someone’s reputation.','libelous'),contexts:[C('libelous.s1','新闻编辑','The newsroom delayed the story until reporters could verify the claim and remove any potentially libelous wording.','编辑部推迟了报道，直到记者核实说法并删除可能构成诽谤的措辞。','The newsroom delayed the story / until reporters could verify the claim / and remove / any potentially libelous wording.','libelous 形容可能构成书面诽谤、损害名誉的内容。','编辑部在核实前避免刊登可能不实且有害的指控。')],mistakes:[M('The comment was libelous because it accurately quoted a public record and made no false claim about anyone.','The comment was potentially libelous because it published a false accusation that damaged someone’s reputation.','准确引用记录不等于发表虚假诽谤内容。')],quiz:[Q('libelous',1,1,'A libelous statement is?','written, false, and damaging to reputation','accurate and harmless','a spoken word with no publication','written, false, and damaging to reputation','libelous 指具有书面诽谤性质的。'),Q('libelous',2,1,'Editors check a claim to avoid publishing?','libelous material','lexical material','a landform','libelous material','核实指控可降低发布诽谤内容的风险。'),Q('libelous',3,1,'Libelous is the adjective related to?','libel','liable','lapse','libel','libelous 由 libel 加 -ous 构成。','word-formation'),Q('libelous',4,1,'Which post is most likely libelous?','a false published claim that a named person stole money','an accurate review of a public lecture','a neutral dictionary definition','a false published claim that a named person stole money','虚假的公开指控损害名誉，可能构成诽谤。')]});
D('liberal',{etymology:E('Liberal comes from Latin liberalis “of freedom”; it can describe an open-minded attitude, political support for freedom and reform, generous amounts, or a broad interpretation.','liberal'),contexts:[C('liberal.s1','校园政策','The principal took a liberal approach to dress choices, allowing students to express different cultural styles.','校长对着装选择采取开明态度，允许学生表达不同的文化风格。','The principal took a liberal approach to dress choices / allowing students / to express / different cultural styles.','liberal.s1 指尊重不同观点或选择、思想开明的。','校规允许多样文化表达。')],mistakes:[M('The school described its policy as liberal even though it punished every harmless difference in dress and forbade personal choice.','The school described its policy as liberal because it respected harmless differences in dress.','严厉禁止无害差异与尊重不同选择相反。')],quiz:[Q('liberal',1,1,'A liberal attitude toward customs is?','open-minded and respectful of differences','hostile to every different practice','a legal debt','open-minded and respectful of differences','liberal.s1 表示开明、尊重差异的。'),Q('liberal',2,2,'A liberal political movement may support?','personal freedom and gradual reform','strict control of every private choice','the elimination of all public discussion','personal freedom and gradual reform','liberal.s2 指支持自由与渐进改革的政治观点。'),Q('liberal',3,3,'A liberal amount of seasoning is?','a generous amount','a tiny amount only','an amount that is legally owed','a generous amount','liberal.s3 表示大量、充足的。'),Q('liberal',4,4,'A liberal interpretation of a rule is?','broad rather than narrowly literal','strictly limited to one literal reading','unrelated to the rule','broad rather than narrowly literal','liberal.s4 指宽泛而不拘泥字面的解释。')]});
D('liberalise',{etymology:E('Liberalise is formed from liberal with -ise; it means make laws, rules, or systems less strict or more open.','liberalise'),contexts:[C('liberalise.s1','贸易政策','The government plans to liberalise import rules gradually while keeping safety inspections in place.','政府计划逐步放宽进口规定，同时保留安全检查。','The government plans to liberalise import rules / gradually / while keeping safety inspections / in place.','liberalise 指使规则、法律或制度变得不那么严格或更加开放。','进口限制将放宽，但安全监管仍保留。')],mistakes:[M('The ministry liberalised the system by adding new permits, bans, and restrictions to every application.','The ministry liberalised the system by removing several unnecessary restrictions.','增加限制使制度更严格，而不是 liberalise。')],quiz:[Q('liberalise',1,1,'To liberalise a regulation is to?','make it less strict or more open','make it impossible to follow','turn it into a dictionary','make it less strict or more open','liberalise 指放宽规则。'),Q('liberalise',2,1,'A country might liberalise trade by?','reducing some import restrictions','adding a ban on every imported good','closing all ports permanently','reducing some import restrictions','减少部分进口限制是放宽贸易。'),Q('liberalise',3,1,'Liberalise is the verb formed from?','liberal','liar','libel','liberal','liberalise 由 liberal 加 -ise 构成。','word-formation'),Q('liberalise',4,1,'If a licensing system is liberalised, applicants may face?','fewer unnecessary restrictions','more prohibitions and conditions','no possibility of applying','fewer unnecessary restrictions','放宽制度通常减少不必要的限制。')]});
D('liberally',{etymology:E('Liberally is the adverb from liberal; it can mean in a generous quantity or in an open-minded or broad, nonliteral way.','liberally'),contexts:[C('liberally.s1','烹饪说明','Brush the vegetables liberally with olive oil so that their cut surfaces do not dry out in the oven.','在蔬菜表面充分刷上橄榄油，避免切面在烤箱中变干。','Brush the vegetables liberally with olive oil / so that their cut surfaces / do not dry out / in the oven.','liberally.s1 表示大方地、充足地使用某物。','说明要求涂上较多橄榄油。')],mistakes:[M('The recipe says to season the soup liberally but instructs the cook to add only one grain of salt to a large pot.','The recipe says to season the soup liberally by adding salt generously and tasting as it cooks.','只加一粒盐并非充足地调味。')],quiz:[Q('liberally',1,1,'To apply oil liberally is to apply it?','generously and in a large amount','not at all','only to one tiny spot','generously and in a large amount','liberally.s1 表示大方、充足地。'),Q('liberally',2,2,'To interpret a phrase liberally is to interpret it?','broadly rather than in a strictly literal way','only by its narrowest possible reading','as a tax payment','broadly rather than in a strictly literal way','liberally.s2 指开明或宽泛地解释。'),Q('liberally',3,1,'Which instruction uses liberally to mean “in a generous quantity”?','Spread the paste liberally over the surface.','Use no paste at all.','Apply one drop to a corner only.','Spread the paste liberally over the surface.','充分涂抹体现数量义。'),Q('liberally',4,1,'Liberally is the adverb from?','liberal','liberation','liability','liberal','liberally 由 liberal 加 -ly 构成。','word-formation')]});
D('liberate',{etymology:E('Liberate comes from Latin liberare “to set free,” from liber “free”; it can release a person from confinement or free someone from a burden or constraint.','liberate'),contexts:[C('liberate.s2','心理支持','The counselor helped the student liberate herself from the fear of making small mistakes in class.','辅导员帮助这名学生摆脱了在课堂上犯小错误的恐惧。','The counselor helped the student / liberate herself from the fear / of making small mistakes / in class.','liberate.s2 比喻使某人摆脱限制、责任或忧虑。','学生不再被犯错恐惧束缚。')],mistakes:[M('The program liberated the student by increasing her fear and preventing her from participating in class.','The program liberated the student by helping her overcome the fear that had kept her silent.','增加恐惧、阻止参与与“摆脱束缚”相反。')],quiz:[Q('liberate',1,1,'To liberate a prisoner is to?','set the person free from confinement','charge the person a levy','put the person in a lair','set the person free from confinement','liberate.s1 指释放或解放。'),Q('liberate',2,2,'To liberate someone from anxiety is to?','help free them from that worry','make them more anxious','give them a dictionary','help free them from that worry','liberate.s2 可指使人摆脱忧虑。'),Q('liberate',3,1,'Which action liberates a captive?','opening the cell and ending the confinement','moving the captive to a smaller cell','adding another restriction','opening the cell and ending the confinement','解除拘禁是释放。'),Q('liberate',4,1,'Liberate is related to Latin liber, meaning?','free','word','land','free','liberate 源自表示“自由”的词。','word-formation')]});
D('liberation',{etymology:E('Liberation comes from Latin liberatio, from liberare “to set free”; it names the act or process of freeing people from imprisonment, occupation, or unjust limits.','liberation'),contexts:[C('liberation.s1','历史纪念','The town marks its liberation from occupation each year with a ceremony honoring the residents who resisted.','这个城镇每年举行仪式，纪念摆脱占领，并向曾经抵抗的居民致敬。','The town marks its liberation from occupation / each year / with a ceremony / honoring the residents who resisted.','liberation 指从监禁、占领或不公平限制中获得自由的过程。','纪念活动庆祝城镇结束被占领状态。')],mistakes:[M('The ceremony celebrated liberation even though the town remained under occupation and residents still could not leave.','The ceremony celebrated liberation after occupying forces withdrew and residents regained freedom.','持续被占领且居民未恢复自由，与 liberation 相反。')],quiz:[Q('liberation',1,1,'Liberation is?','the act or process of setting people free','the imposition of a new prison sentence','a list of dictionary words','the act or process of setting people free','liberation 指解放或释放的过程。'),Q('liberation',2,1,'A town celebrates liberation when it?','is freed from occupation','is occupied for the first time','adds a tax levy','is freed from occupation','摆脱占领可称为解放。'),Q('liberation',3,1,'Liberation is the noun related to?','liberate','liable','lexical','liberate','liberation 是 liberate 的名词形式。','word-formation'),Q('liberation',4,1,'Which event is a liberation?','prisoners are released from unjust confinement','a new fee is imposed on them','a dictionary is printed','prisoners are released from unjust confinement','释放被不公正拘禁者属于 liberation。')]});
D('liberty',{etymology:E('Liberty comes through Old French from Latin libertas “freedom”; it can mean freedom from oppression, a right or permission, or excessive familiarity without consent.','liberty'),contexts:[C('liberty.s3','社交边界','The visitor took the liberty of opening the host’s desk without asking, which made the host uncomfortable.','来访者未经询问便擅自打开主人的书桌，让主人感到不舒服。','The visitor took the liberty / of opening the host’s desk / without asking / which made the host uncomfortable.','liberty.s3 常见于 take the liberty of，表示未经许可擅自做某事。','未获允许便打开别人的书桌越过了社交界限。')],mistakes:[M('She took the liberty of using the private office after receiving the owner’s explicit permission and invitation.','She took the liberty of entering the private office without asking its owner.','事先获得明确许可，不属于擅自越界。')],quiz:[Q('liberty',1,1,'Political liberty is?','freedom from imprisonment or oppressive control','a legal claim securing a debt','a short dictionary entry','freedom from imprisonment or oppressive control','liberty.s1 指自由、不受拘禁或压迫。'),Q('liberty',2,2,'A liberty granted by law is?','a right or permission','a debt owed to a bank','an act of hiding','a right or permission','liberty.s2 可指法律赋予的权利或许可。'),Q('liberty',3,3,'“He took the liberty of borrowing the car” may suggest he?','did so without asking first','had formal written permission','was arrested for larceny','did so without asking first','该短语可表示未经许可擅自做某事。'),Q('liberty',4,2,'Which is an example of personal liberty?','the right to speak freely','a duty to repay a loan','a restriction against every choice','the right to speak freely','言论自由是一种权利。')]});
D('librarian',{etymology:E('Librarian is formed from library with the agent suffix -ian; it names a professional who manages collections and helps people find information.','librarian'),contexts:[C('librarian.s1','公共图书馆','The librarian helped a visitor locate local history records and showed her how to request a digital copy.','图书馆员帮助一位访客找到地方史资料，并教她如何申请电子副本。','The librarian helped a visitor / locate local history records / and showed her / how to request a digital copy.','librarian 指管理图书馆资源并协助读者查找信息的专业人员。','图书馆员提供检索和资料获取帮助。')],mistakes:[M('The librarian refused to manage any collection or help readers and worked only as a tenant renting a room in the building.','The librarian organized the collection and helped readers locate reliable sources.','单纯租用房间并不构成图书馆员职责。')],quiz:[Q('librarian',1,1,'A librarian usually helps people?','find and use library information','levy a tax','repair a cliff after a landslip','find and use library information','librarian 指图书馆管理员或馆员。'),Q('librarian',2,1,'Which task suits a librarian?','helping a reader locate an archive record','painting a landscape as a full-time artist','issuing a parking fine','helping a reader locate an archive record','帮助读者检索档案是图书馆员常见工作。'),Q('librarian',3,1,'Librarian is related to the word?','library','libel','lichen','library','librarian 从 library 派生。','word-formation'),Q('librarian',4,1,'A librarian may teach someone how to?','search a catalog for a book','collect a tax levy','climb a ladder safely','search a catalog for a book','图书馆员可教读者使用目录检索。')]});
D('library',{etymology:E('Library comes from Latin librarium, “chest or place for books,” from liber “book”; it can mean a public collection, a personal collection, or a reusable digital collection.','library'),contexts:[C('library.s3','软件开发','The application uses a graphics library so its developers can reuse tested functions instead of writing every routine from scratch.','该应用使用图形库，使开发人员可以复用经过测试的功能，而不必从头编写每个程序。','The application uses a graphics library / so its developers can reuse tested functions / instead of writing every routine / from scratch.','library.s3 指供程序重复使用的一组文件、程序或工具。','开发者调用现成代码库中的功能。')],mistakes:[M('The program used no library because it imported a reusable collection of tested functions and resources.','The program used a library to reuse tested functions and resources.','导入可重用资源正是使用软件库。')],quiz:[Q('library',1,1,'A public library is a place where people may?','read or borrow books','pay a land levy','store wet soil','read or borrow books','library.s1 指图书馆或图书室。'),Q('library',2,2,'A person’s library may be?','their collection of books or records','a public swimming lane','a legal claim on property','their collection of books or records','library.s2 可指个人收藏。'),Q('library',3,3,'A software library is?','a stored collection of reusable programs or files','a building that lends paper books','an isolated island','a stored collection of reusable programs or files','library.s3 指可复用的软件资源集合。'),Q('library',4,1,'Which place is a library?','a room where visitors borrow books','a store that sells only groceries','a ship’s larboard','a room where visitors borrow books','可供读者借阅图书的场所是图书馆。')]});
D('license',{etymology:E('License comes through Old French from Latin licentia “freedom or permission”; it can mean an official permit, freedom to act, or the verb for granting authorization.','license'),contexts:[C('license.s3','行业监管','The state licenses electricians only after they pass the safety examination and document supervised training.','州政府只有在电工通过安全考试并提交受监督培训记录后，才向其发放执照。','The state licenses electricians / only after they pass the safety examination / and document / supervised training.','license.s3 作动词，表示正式批准或发给执照。','电工需满足考试和培训要求后获准执业。')],mistakes:[M('The agency licensed the contractor by refusing to review qualifications and formally denying permission to work.','The agency licensed the contractor after verifying qualifications and granting permission to work.','正式拒绝许可与发放执照相反。')],quiz:[Q('license',1,1,'A driver’s license is?','an official document permitting someone to drive','a collection of books','a false written accusation','an official document permitting someone to drive','license.s1 指正式许可证或执照。'),Q('license',2,2,'Literary license can mean?','freedom to depart from usual rules','a debt recorded on a balance sheet','a professional dictionary','freedom to depart from usual rules','license.s2 可指较自由的做法或表达空间。'),Q('license',3,3,'To license a clinic is to?','officially authorize it to operate','close it without explanation','give it a library collection','officially authorize it to operate','license.s3 表示正式批准经营。'),Q('license',4,3,'Which action licenses a business?','the authority issues its required permit','the owner hides its application','a customer reads its website','the authority issues its required permit','主管机关签发许可即是批准经营。')]});
D('licensed',{etymology:E('Licensed is the past participle of license used as an adjective; it means officially permitted to operate or perform a regulated job.','licensed'),contexts:[C('licensed.s1','职业资格','Only a licensed electrician may replace the building’s main circuit breaker under local safety rules.','根据当地安全规定，只有持证电工才可以更换大楼的主断路器。','Only a licensed electrician / may replace the building’s main circuit breaker / under local safety rules.','licensed 表示已获得官方许可或执照的。','该工作受规定限制，须由持证人员完成。')],mistakes:[M('The contractor was licensed even though the regulator had rejected the application and issued no permit.','The contractor was licensed after the regulator approved the application and issued a permit.','申请被拒且未获许可，不能称为持证。')],quiz:[Q('licensed',1,1,'A licensed electrician is?','officially authorized to do the work','someone who has never applied for permission','a person who writes a lexicon','officially authorized to do the work','licensed 指获准从事该工作的。'),Q('licensed',2,1,'Which business is licensed?','one that has received the required operating permit','one whose permit application was denied','one that avoids all regulation','one that has received the required operating permit','获发经营许可的企业属于 licensed。'),Q('licensed',3,1,'Licensed is formed from which verb?','license','libel','languish','license','licensed 是 license 的过去分词形式。','word-formation'),Q('licensed',4,1,'A licensed professional can?','perform work covered by the issued authorization','ignore every safety requirement','issue a lien against any property','perform work covered by the issued authorization','执照授权其从事规定范围内的工作。')]});
D('lichen',{etymology:E('Lichen comes from Greek leichen, “tree moss”; a lichen is a composite organism formed by a fungus living with an alga or cyanobacterium.','lichen'),contexts:[C('lichen.s1','野外生态','Pale lichen spread over the north side of the stone wall, where moisture and shade supported its slow growth.','浅色地衣蔓延在石墙北侧，那里潮湿且阴凉，适合它缓慢生长。','Pale lichen spread over the north side of the stone wall / where moisture and shade / supported its slow growth.','lichen 指由真菌与藻类或蓝细菌共同构成的复合生物。','潮湿阴凉的石面上可见地衣生长。')],mistakes:[M('The botanist labeled a single green leaf lichen even though it was a plant leaf with no fungal partner.','The botanist identified the crusty growth as lichen, a partnership of fungus and alga.','单独一片植物叶并非真菌与藻类组成的地衣。')],quiz:[Q('lichen',1,1,'A lichen is formed by a fungus living with?','an alga or cyanobacterium','a ladder or a lantern','a sheep or a lamb','an alga or cyanobacterium','lichen 是真菌与藻类或蓝细菌组成的复合生物。'),Q('lichen',2,1,'Where might lichen grow?','on a shaded, damp stone wall','inside a sealed dry envelope','under a polished lampshade only','on a shaded, damp stone wall','地衣常可附着在潮湿的石面或树皮上。'),Q('lichen',3,1,'Which observation suggests lichen?','a crusty organism covering a rock','one loose flower petal','a metal license plate','a crusty organism covering a rock','岩石表面的壳状生物可能是地衣。'),Q('lichen',4,1,'Lichen is a composite organism rather than?','a single ordinary plant','a fungus-alga partnership','a growth on a rock','a single ordinary plant','地衣由不同生物伙伴共同构成，不是单一普通植物。')]});
D('lick',{etymology:E('Lick comes from Old English liccian; it can mean pass the tongue over something, describe a flame or wave touching lightly, or name one quick tongue movement.','lick'),contexts:[C('lick.s2','火焰描写','Small flames began to lick the edge of the damp wood before the fire caught properly.','火势完全燃起前，小火苗已经开始轻轻舔舐潮湿木材的边缘。','Small flames began to lick the edge / of the damp wood / before the fire caught / properly.','lick.s2 描写火焰或波浪轻轻触碰、掠过某物。','火苗沿木材边缘轻轻掠过。')],mistakes:[M('The flame licked the wood by remaining several meters away and never touching or approaching it.','The flame licked the wood as small tongues of fire touched its edge.','从未靠近或触及的火焰不能称为舔舐木材。')],quiz:[Q('lick',1,1,'A dog may lick its paw by?','passing its tongue over it','covering it with a lid','measuring it with a ruler','passing its tongue over it','lick.s1 指用舌头舔。'),Q('lick',2,2,'Flames lick a wall when they?','touch or flicker lightly across it','freeze in place','form a written lien','touch or flicker lightly across it','lick.s2 可形容火焰轻轻掠过。'),Q('lick',3,3,'A lick of cream is?','a small amount put on with one tongue movement','a full bowl of soup','a kind of library','a small amount put on with one tongue movement','lick.s3 可指一舔或少量。'),Q('lick',4,1,'Which sentence uses lick literally?','The child licked the spoon clean.','The council levied a fee.','The waves licked the seawall.','The child licked the spoon clean.','此处是人用舌头舔勺子。','context')]});
D('lid',{etymology:E('Lid comes from Old English hlid, a covering; it can mean a removable cover on a container or the movable skin that covers an eye.','lid'),contexts:[C('lid.s2','眼科检查','The clinician examined the upper lid after the patient reported swelling around the eye.','患者报告眼周肿胀后，临床医生检查了上眼睑。','The clinician examined the upper lid / after the patient reported / swelling / around the eye.','lid.s2 指覆盖眼球的可活动皮肤，即眼睑。','检查对象是眼睛上方的皮肤褶皱。')],mistakes:[M('The doctor examined the jar’s lid for eye swelling even though the patient’s eyelid was the affected area.','The doctor examined the patient’s eyelid for swelling.','罐子盖子 lid.s1 不能指眼部皮肤。')],quiz:[Q('lid',1,1,'A jar lid is?','a removable cover','the skin over an eye','a type of lichen','a removable cover','lid.s1 指容器盖。'),Q('lid',2,2,'An eyelid is?','the movable skin covering the eye','a cover on a jar','a computer library','the movable skin covering the eye','lid.s2 指眼睑。'),Q('lid',3,1,'Which action closes a container lid?','placing the cover over its opening','covering the eye with a hand','moving a ship landward','placing the cover over its opening','lid.s1 的容器义是盖住开口的盖子。'),Q('lid',4,2,'A doctor treating a swollen lid would examine?','the skin around the eye','the cap of a bottle','the edge of a cliff','the skin around the eye','眼睑属于眼部皮肤。')]});
D('lie',{etymology:E('Lie has distinct Old English roots: licgan for resting or being situated, and lygean for telling an untruth; the noun lie names a false statement.','lie'),contexts:[C('lie.s3','问题分析','The main weakness of the proposal lies in its assumption that every household has reliable internet access.','该提案的主要弱点在于它假设每户家庭都能稳定上网。','The main weakness of the proposal / lies in its assumption / that every household / has reliable internet access.','lie.s3 常用 lie in，表示核心原因或要点在于某事。','提案的问题源于其未经验证的假设。'),C('lie.s4','事实核查','The official admitted that he had lied about the meeting date after the calendar entry was published.','日历记录公开后，这名官员承认自己谎报了会议日期。','The official admitted / that he had lied about the meeting date / after the calendar entry / was published.','lie.s4 指明知不实仍说出某事；过去式是 lied。','他说日期时知道与真实日历不符。')],mistakes:[M('The witness lied about the time by accurately reporting the time shown on the recording and correcting an earlier error.','The witness lied about the time by knowingly giving a false account.','如实报告并纠正错误不是说谎。')],quiz:[Q('lie',1,1,'To lie on a bed is to?','rest in a flat position','state something known to be false','owe money to a creditor','rest in a flat position','lie.s1 指躺下或平卧。'),Q('lie',2,3,'“The answer lies in the final paragraph” means the answer?','is found or consists there','is physically lying on the floor','is a deliberate falsehood','is found or consists there','lie.s3 表示要点或所在之处。'),Q('lie',3,4,'To lie about a meeting is to?','knowingly say something untrue about it','attend the meeting on time','write the minutes accurately','knowingly say something untrue about it','lie.s4 指故意说不实的话。'),Q('lie',4,5,'A lie is?','a statement known to be untrue','a person resting on a sofa','a location on a map','a statement known to be untrue','lie.s5 作名词指谎言。')]});
D('lie in',{etymology:E('Lie in is a phrasal verb using lie “be situated”; in this sense, the central reason or substance of something lies in a particular fact.','lie in'),contexts:[C('lie in.s1','逻辑推理','The strength of the argument lies in its careful comparison of costs over the full life of the project.','这个论证的力量在于它仔细比较了项目整个生命周期的成本。','The strength of the argument lies in / its careful comparison of costs / over the full life / of the project.','lie in 表示某事的核心、原因或基础在于后接内容。','论证的说服力源于对全周期成本的比较。')],mistakes:[M('The success of the plan lies in its failure to address any of the stated goals.','The success of the plan lies in its effective response to the stated goals.','没有回应目标不能成为计划成功的基础。')],quiz:[Q('lie in',1,1,'“The difficulty lies in the timing” means the difficulty?','is caused by or found in the timing','is sleeping on a bed','is a false statement','is caused by or found in the timing','lie in 表示问题所在或原因在于。'),Q('lie in',2,1,'Which sentence uses lie in correctly?','The value lies in the data’s long-term comparison.','The value lies under false words.','The value lies to its owner.','The value lies in the data’s long-term comparison.','该句说明价值的所在是长期比较。'),Q('lie in',3,1,'The solution may lie in better planning means it?','may be found in better planning','is asleep during planning','has been written as a lie','may be found in better planning','lie in 可表示解决办法存在于某处或某种方式中。'),Q('lie in',4,1,'Lie in is closest to “consist in” when describing?','the basis or essential feature of something','a person resting horizontally','a deliberate false statement','the basis or essential feature of something','lie in 可指本质或基础在于。','confusable')]});
D('lie low',{etymology:E('Lie low combines lie “remain” and low; it is an informal phrasal verb meaning stay hidden or avoid attention for a period.','lie low'),contexts:[C('lie low.s1','新闻调查','After receiving threats, the whistleblower decided to lie low while the lawyers arranged a secure place to stay.','收到威胁后，这名举报者决定暂时躲避风头，等待律师安排安全住处。','After receiving threats / the whistleblower decided to lie low / while the lawyers arranged / a secure place to stay.','lie low 指暂时躲藏或避免引人注意。','举报者为安全起见暂时不公开露面。')],mistakes:[M('The fugitive decided to lie low by holding a press conference and publishing his exact location online.','The fugitive decided to lie low by avoiding public appearances and changing where he stayed.','公开曝光行踪与躲避注意相反。')],quiz:[Q('lie low',1,1,'To lie low for a while is to?','stay hidden and avoid attention','lie flat on a beach to sunbathe','say something untrue','stay hidden and avoid attention','lie low 指暂时蛰伏或躲避。'),Q('lie low',2,1,'Who might lie low?','a threatened witness avoiding public attention','a speaker giving a live televised interview','a librarian recommending books','a threatened witness avoiding public attention','受威胁者可能暂时避开公众视线。'),Q('lie low',3,1,'Which action helps someone lie low?','keeping a temporary location private','posting their address publicly','announcing every movement','keeping a temporary location private','不公开暂住地点有助于躲避注意。'),Q('lie low',4,1,'Lie low is an informal?','phrasal verb','noun for a debt','adjective for a dictionary','phrasal verb','lie low 是非正式短语动词。','word-formation')]});
D('lie under',{etymology:E('Lie under combines lie “be situated” and under; figuratively, it describes a hidden principle or cause on which something rests.','lie under'),contexts:[C('lie under.s1','制度分析','A belief in equal access lies under the school’s policy of providing free meals to students who need them.','平等获取机会的信念构成了学校为有需要的学生提供免费餐食政策的基础。','A belief in equal access lies under / the school’s policy / of providing free meals / to students who need them.','lie under 比喻构成某制度、观点或行动的隐含基础。','平等理念支撑免费餐食政策。')],mistakes:[M('No principle lay under the policy because the policy rested on a clear commitment to equal access.','A commitment to equal access lay under the policy and explained its free-meal provision.','既然政策建立在平等承诺上，就不是“没有基础原则”。')],quiz:[Q('lie under',1,1,'A principle that lies under a policy is?','its hidden basis or foundation','a false claim about it','a lid covering a container','its hidden basis or foundation','lie under 比喻构成基础。'),Q('lie under',2,1,'“Trust lies under the partnership” means trust?','forms its underlying basis','is physically sleeping beneath a table','has been levied as a fee','forms its underlying basis','这里表示伙伴关系以信任为基础。'),Q('lie under',3,1,'Which idea could lie under a public program?','the principle that all residents deserve access','a random detail unrelated to the program','a librarian’s lunch','the principle that all residents deserve access','普遍服务理念可以成为项目基础。'),Q('lie under',4,1,'Lie under is used figuratively to mean?','underpin or form the basis of','publish a written accusation','recline beneath an object only','underpin or form the basis of','lie under 可比喻为某事提供基础。','confusable')]});
D('lien',{etymology:E('Lien comes through Anglo-French from a word meaning bond or tie; it names a creditor’s legal claim on property as security for a debt.','lien'),contexts:[C('lien.s1','房产交易','The contractor placed a lien on the property after the owner failed to pay for the completed roof repairs.','业主未支付已完成的屋顶维修费用后，承包商对该房产设立了留置权。','The contractor placed a lien on the property / after the owner failed to pay / for the completed roof repairs.','lien 指债权人因债务未清而对特定财产享有的法律请求或担保权。','承包商以房产权益保障未支付的工程款。')],mistakes:[M('The contractor released the lien while keeping no legal claim on the property and confirming that the repair debt was fully paid.','The contractor placed a lien on the property to secure the unpaid repair debt.','确认欠款已付并放弃财产请求权，与设立 lien 相反。')],quiz:[Q('lien',1,1,'A lien is a creditor’s legal claim on?','property securing a debt','a dictionary’s word list','a ship’s left side','property securing a debt','lien 指以财产担保债务的法律权利。'),Q('lien',2,1,'A contractor may seek a lien when?','the owner has not paid for completed work','the bill has been paid in full','the owner lends a ladder','the owner has not paid for completed work','未获工程款时，承包商可能通过 lien 保障债权。'),Q('lien',3,1,'Which statement describes a lien?','a legal claim tied to property until a debt is addressed','a tax collected from every library visitor','a license to practice medicine','a legal claim tied to property until a debt is addressed','lien 将债权与特定财产相连。'),Q('lien',4,1,'Lien is a term from?','property and debt law','botany','phonetics','property and debt law','lien 是财产与债务法律术语。')]});
D('lieu',{etymology:E('Lieu comes from Old French lieu, “place,” from Latin locus; in modern English it survives chiefly in the phrase in lieu of, meaning instead of.','lieu'),contexts:[C('lieu.s1','工作安排','The employee received a day off in lieu of overtime pay under the agreement.','根据协议，员工获得一天补休，以代替加班费。','The employee received a day off / in lieu of overtime pay / under the agreement.','lieu 几乎只用于 in lieu of，表示代替或作为替代。','补休取代了加班费。')],mistakes:[M('The employee received overtime pay in lieu of a day off, meaning the two were both given as replacements for one another.','The employee received a day off in lieu of overtime pay.','in lieu of 表示前者代替后者，不能把替代关系颠倒。')],quiz:[Q('lieu',1,1,'“In lieu of” means?','instead of','in addition to','because of','instead of','lieu 主要用于 in lieu of，意思是代替。'),Q('lieu',2,1,'A day off in lieu of overtime pay is?','a day off instead of the pay','a day off plus the full pay','a day off before any overtime is worked','a day off instead of the pay','补休取代加班费。'),Q('lieu',3,1,'Which sentence uses lieu correctly?','She chose tea in lieu of coffee.','She chose lieu the coffee.','She chose tea in lieu from coffee.','She chose tea in lieu of coffee.','固定搭配为 in lieu of。','collocation'),Q('lieu',4,1,'Lieu is most often used with which preposition in the phrase?','of','by','under','of','in lieu of 是固定搭配。','collocation')]});
D('lieutenant',{etymology:E('Lieutenant comes from French lieu “place” and tenant “holding,” originally one who acts in another’s place; it names a military rank or a deputy.','lieutenant'),contexts:[C('lieutenant.s2','机构管理','The director’s lieutenant handled daily approvals while the director was traveling abroad.','主任出国期间，他的副手负责日常审批。','The director’s lieutenant handled daily approvals / while the director / was traveling / abroad.','lieutenant.s2 指代替较高职位者行事的副手或助理官员。','副手在主任缺席时承担审批工作。')],mistakes:[M('The director’s lieutenant was the person with no authority who could not act or make decisions in the director’s absence.','The director’s lieutenant acted on the director’s behalf during the trip.','无法代行职责的人不是此处所说的副手。')],quiz:[Q('lieutenant',1,1,'A military lieutenant holds?','an officer rank below captain in many forces','the highest rank in every army','a legal claim on a house','an officer rank below captain in many forces','lieutenant.s1 是许多军队中低于 captain 的军官级别。'),Q('lieutenant',2,2,'A manager’s lieutenant is?','a deputy who acts for the manager','a person who rents the manager’s home','a dictionary compiler','a deputy who acts for the manager','lieutenant.s2 指代行职责的副手。'),Q('lieutenant',3,2,'Who is acting as the director’s lieutenant?','the deputy approving routine requests during the director’s absence','a visitor with no authority','the director’s landlord','the deputy approving routine requests during the director’s absence','主任不在时处理事务的人是副手。'),Q('lieutenant',4,1,'Lieutenant is related historically to the idea of?','holding someone’s place','paying a tax','writing a false report','holding someone’s place','法语词源原指代某人履职。','word-formation')]});
D('life',{etymology:E('Life comes from Old English lif; it can mean being alive, the span from birth to death, a way of living, energy, or living organisms collectively.','life'),contexts:[C('life.s5','生物多样性','Life on the island includes nesting seabirds, native grasses, and several rare lizards.','岛上的生物包括筑巢海鸟、本土草类和几种珍稀蜥蜴。','Life on the island includes nesting seabirds / native grasses / and several rare lizards.','life.s5 可指某一类或某处的生物。','列出的动物和植物都是岛上生物。'),C('life.s3','城市规划','The new evening bus route improved life for shift workers who previously had no safe way to get home.','新的夜间公交线路改善了轮班工人的生活，此前他们没有安全回家的方式。','The new evening bus route improved life / for shift workers / who previously had no safe way / to get home.','life.s3 可指个人或群体日常生活的方式与状况。','公交改善了工人的日常出行条件。')],mistakes:[M('The service improved life for shift workers by leaving them with fewer safe transport options and longer waits.','The service improved life for shift workers by providing a reliable late bus home.','减少安全出行方式不会改善生活。')],quiz:[Q('life',1,1,'Life in the biological sense is?','the condition of being alive','a person’s exact birth date only','a written tax claim','the condition of being alive','life.s1 指生命或生存状态。'),Q('life',2,2,'A long life is?','the period between birth and death','a single afternoon','a collection of dictionary entries','the period between birth and death','life.s2 指一生或寿命。'),Q('life',3,3,'A change in city life concerns?','the way people live day to day','only the number of living organisms','a military rank','the way people live day to day','life.s3 指生活方式或日常生活。'),Q('life',4,4,'A performance needs more life when it needs?','more energy and interest','a longer legal claim','a quieter library','more energy and interest','life.s4 可指活力、生气。')]});
D('life-size',{etymology:E('Life-size combines life and size; it describes an image or model that matches the actual dimensions of the living person or object.','life-size'),contexts:[C('life-size.s1','博物馆展览','The museum displayed a life-size model of a blue whale so visitors could appreciate its full length.','博物馆展出了一具与实物等大的蓝鲸模型，让游客了解它的完整长度。','The museum displayed a life-size model / of a blue whale / so visitors could appreciate / its full length.','life-size 指与真人或原物尺寸相同的。','模型长度与真实蓝鲸相符。')],mistakes:[M('The gallery described a hand-sized whale figurine as life-size even though a real whale is vastly larger.','The gallery described the full-length whale model as life-size.','手掌大小的模型远小于真实蓝鲸。')],quiz:[Q('life-size',1,1,'A life-size statue is?','the same size as the real person','much smaller than the real person','a picture of a person’s way of living','the same size as the real person','life-size 指与真人一样大。'),Q('life-size',2,1,'Which model is life-size?','a full-length replica matching the original’s dimensions','a tiny keychain version','a drawing on a postage stamp','a full-length replica matching the original’s dimensions','尺寸与原物相同的复制品是 life-size。'),Q('life-size',3,1,'A life-size display helps viewers judge?','the object’s actual dimensions','its dictionary definition','its legal liability','the object’s actual dimensions','等大模型能呈现实物尺寸。'),Q('life-size',4,1,'Life-size is written with a?','hyphen','comma inside the word','space between life and hyphen only','hyphen','life-size 通常带连字符。','spelling')]});
D('lifeblood',{etymology:E('Lifeblood combines life and blood; literally it means blood necessary for life and figuratively the essential resource that keeps an activity or group functioning.','lifeblood'),contexts:[C('lifeblood.s1','地方经济','Small family farms are the lifeblood of the valley’s economy, supplying local markets and seasonal work.','小型家庭农场是山谷经济的命脉，为本地市场提供农产品和季节性工作。','Small family farms are the lifeblood / of the valley’s economy / supplying local markets / and seasonal work.','lifeblood 比喻维持某个群体或活动运转的关键资源。','农场提供食物和工作，支撑地方经济。')],mistakes:[M('The report called an optional decoration the lifeblood of the hospital even though patient care depended on staff and medicine instead.','The report called reliable electricity the lifeblood of the hospital because its essential systems depended on it.','可有可无的装饰不是维持医院运转的核心资源。')],quiz:[Q('lifeblood',1,1,'The lifeblood of an organization is?','the essential thing that keeps it functioning','a decorative extra with no purpose','a list of its employees','the essential thing that keeps it functioning','lifeblood 比喻维持组织运转的命脉。'),Q('lifeblood',2,1,'If tourism is a town’s lifeblood, tourism?','supports the town’s survival and economy','is unrelated to the town','is a blood test','supports the town’s survival and economy','旅游业支撑城镇经济与生计。'),Q('lifeblood',3,1,'Which could be the lifeblood of a research lab?','steady funding that pays for essential work','an unused poster in the hallway','a broken lid','steady funding that pays for essential work','持续经费支撑实验室开展核心工作。'),Q('lifeblood',4,1,'Lifeblood combines life and?','blood','librarian','liability','blood','lifeblood 是 life 与 blood 的复合词。','word-formation')]});
D('lifeless',{etymology:E('Lifeless combines life and the negative suffix -less; it means without life or lacking energy, movement, or interest.','lifeless'),contexts:[C('lifeless.s1','海滩救援','The rescue team found a lifeless seal on the shore and called a wildlife specialist to assess it.','救援队在岸边发现一只没有生命迹象的海豹，便联系野生动物专家进行评估。','The rescue team found a lifeless seal / on the shore / and called a wildlife specialist / to assess it.','lifeless 可指没有生命的，也可形容缺乏活力或兴趣。','海豹没有生命迹象，因此需要专业评估。')],mistakes:[M('The field guide called the seal lifeless even though it was breathing, moving, and swimming back to the water.','The field guide called the seal lifeless because it showed no breathing or movement.','有呼吸、活动并游动说明动物仍有生命。')],quiz:[Q('lifeless',1,1,'A lifeless body is?','without signs of life','full of energy','lifelike and moving','without signs of life','lifeless.s1 指没有生命的。'),Q('lifeless',2,1,'A lifeless performance is?','dull and lacking energy','exciting and expressive','a full-length model','dull and lacking energy','lifeless 也可形容表演死气沉沉。'),Q('lifeless',3,1,'Which scene looks lifeless?','a motionless plant with dry brittle leaves','a lively crowd dancing','a healthy seal swimming','a motionless plant with dry brittle leaves','枯萎且无活动的景象显得没有生气。'),Q('lifeless',4,1,'The suffix -less in lifeless means?','without','full of','able to','without','-less 表示缺少或没有。','word-formation')]});
D('lifelike',{etymology:E('Lifelike combines life and like; it means resembling a living person or thing so closely that it appears real.','lifelike'),contexts:[C('lifelike.s1','医学模型','The lifelike mannequin had flexible joints and realistic skin texture for practicing emergency procedures.','这具逼真的人体模型有关节活动结构和真实的皮肤纹理，可用于急救练习。','The lifelike mannequin had flexible joints / and realistic skin texture / for practicing / emergency procedures.','lifelike 形容外观或动作非常像真实的生物或物体。','逼真的皮肤质感让模型看起来接近真人。')],mistakes:[M('The artist called the wooden figure lifelike even though it had no recognizable form, features, or resemblance to a living person.','The artist called the carefully detailed portrait lifelike because it closely resembled its subject.','没有任何相似特征的物体不能称为逼真。')],quiz:[Q('lifelike',1,1,'A lifelike model?','resembles a real living thing closely','has no recognizable features','is without life or movement only','resembles a real living thing closely','lifelike 指逼真、像活物的。'),Q('lifelike',2,1,'Which sculpture is lifelike?','one with realistic features and natural posture','one made of abstract blocks with no resemblance','one that is a blank slab','one with realistic features and natural posture','逼真的特征和姿态使雕像像真实人物。'),Q('lifelike',3,1,'A lifelike drawing of a bird should?','closely resemble an actual bird','be a dictionary entry','contain no shape or detail','closely resemble an actual bird','画作需要与真实鸟类相似。'),Q('lifelike',4,1,'Lifelike is formed from life and?','like','less','lien','like','lifelike 表示“像生命/活物一样”。','word-formation')]});
D('lifeline',{etymology:E('Lifeline combines life and line; it can be a rope used to rescue someone or a crucial source of help that prevents failure or danger.','lifeline'),contexts:[C('lifeline.s1','海上救援','The crew threw a lifeline to the sailor in the water and pulled him toward the rescue boat.','船员把救生索扔给落水水手，并把他拉向救援艇。','The crew threw a lifeline / to the sailor in the water / and pulled him / toward the rescue boat.','lifeline 指救援用的绳索，也比喻危急时刻至关重要的帮助。','绳索帮助落水者脱离危险。')],mistakes:[M('The crew offered a lifeline by cutting the only rope and leaving the swimmer beyond reach.','The crew offered a lifeline by throwing a rescue rope within the swimmer’s reach.','切断救援绳并让人够不到它，不是提供帮助。')],quiz:[Q('lifeline',1,1,'A physical lifeline can be?','a rope used to rescue someone','a heavy legal debt','a type of orchid petal','a rope used to rescue someone','lifeline.s1 可指救援用绳索。'),Q('lifeline',2,1,'A grant may be a lifeline for a small clinic if it?','provides essential help in a crisis','adds a decorative sign only','has no effect on operations','provides essential help in a crisis','lifeline 也比喻关键援助。'),Q('lifeline',3,1,'Which action gives a swimmer a lifeline?','throwing a rescue rope toward them','moving the boat farther away','turning off the harbor light','throwing a rescue rope toward them','救生索能让游泳者抓住并获救。'),Q('lifeline',4,1,'The business called its emergency loan a lifeline because it?','kept the business operating through a crisis','made the crisis worse','was an ordinary decoration','kept the business operating through a crisis','紧急贷款帮助企业渡过危机。')]});
D('lifelong',{etymology:E('Lifelong combines life and long; it describes something that continues throughout a person’s life.','lifelong'),contexts:[C('lifelong.s1','个人经历','A lifelong interest in astronomy led Dr. Chen to build a small observatory in her garden.','陈博士终身对天文学感兴趣，这促使她在花园里建了一座小型天文台。','A lifelong interest in astronomy / led Dr. Chen / to build a small observatory / in her garden.','lifelong 表示持续一生的。','兴趣从早年一直延续到成年后的生活。')],mistakes:[M('He described his lifelong hobby as one he tried once for an afternoon and never returned to.','He described his lifelong hobby as an activity he had pursued for decades.','只尝试一次且不再继续，不能称为终身爱好。')],quiz:[Q('lifelong',1,1,'A lifelong friendship lasts?','throughout the friends’ lives','for one brief afternoon','until the next bus arrives','throughout the friends’ lives','lifelong 指持续一生的。'),Q('lifelong',2,1,'Which is a lifelong interest?','a passion for music maintained over many decades','a hobby tried once and immediately forgotten','a short-term project lasting one day','a passion for music maintained over many decades','长期持续数十年的兴趣可称 lifelong。'),Q('lifelong',3,1,'Lifelong combines life with?','long','less','line','long','lifelong 表示 life-long，即持续一生。','word-formation'),Q('lifelong',4,1,'A lifelong learner continues learning?','throughout life','only before age ten','only while at school','throughout life','终身学习贯穿一生。')]});
D('lifesaver',{etymology:E('Lifesaver combines life and saver; it means a person who rescues someone from danger or, figuratively, a great help in an urgent situation.','lifesaver'),contexts:[C('lifesaver.s1','急救培训','The trained lifeguard was a lifesaver when she pulled the exhausted swimmer from the current.','受过训练的救生员把筋疲力尽的游泳者从急流中救出，成了救命恩人。','The trained lifeguard was a lifesaver / when she pulled the exhausted swimmer / from the current.','lifesaver.s1 指救人性命的人，也可指危急时刻起重大作用的事物。','救生员及时把游泳者从危险水流中拉出。')],mistakes:[M('The guard was called a lifesaver even though she saw the swimmer in danger and refused to help.','The guard was called a lifesaver after rescuing the swimmer from the current.','看见危险却拒绝救援，不符合“救命者”的意思。')],quiz:[Q('lifesaver',1,1,'A lifesaver may be?','someone who rescues a person from danger','someone who creates a hazard','a person who writes a dictionary','someone who rescues a person from danger','lifesaver 指救生者。'),Q('lifesaver',2,1,'A spare key can be a lifesaver when?','you are locked out of your home','you already have the right key in hand','you are reading a lexicon','you are locked out of your home','备用钥匙在被锁在门外时能解急。'),Q('lifesaver',3,1,'Which person acted as a lifesaver?','a swimmer who pulled a child from deep water','a bystander who walked away','a librarian who closed the library','a swimmer who pulled a child from deep water','从深水中救出孩子的人救了他的性命。'),Q('lifesaver',4,1,'In “That checklist was a lifesaver,” the checklist was?','extremely helpful in a difficult moment','a person who swims professionally','a legal liability','extremely helpful in a difficult moment','此处 lifesaver 比喻及时有用的帮助。')]});
D('lifespan',{etymology:E('Lifespan combines life and span; it names the length of time a person or animal lives or, figuratively, how long a product remains usable.','lifespan'),contexts:[C('lifespan.s2','产品维修','The repair extended the pump’s lifespan by five years and delayed the need to replace the whole unit.','这次维修把水泵的使用寿命延长了五年，推迟了更换整台设备的需要。','The repair extended the pump’s lifespan / by five years / and delayed the need / to replace the whole unit.','lifespan.s2 指产品或机器可使用的年限。','维修让机器保持可用更久。')],mistakes:[M('The repair shortened the pump’s lifespan by five years because it made the machine remain usable for five extra years.','The repair extended the pump’s lifespan by five years.','延长可用时间与缩短寿命的说法矛盾。')],quiz:[Q('lifespan',1,1,'A person’s lifespan is?','the length of time they live','the way they spend each day','their legal right to speak','the length of time they live','lifespan.s1 指人或动物的寿命。'),Q('lifespan',2,2,'A machine’s lifespan is?','the period it can be used','the size of its light bulb','the number of people who repair it','the period it can be used','lifespan.s2 指设备的使用期限。'),Q('lifespan',3,1,'Which action may extend a device’s lifespan?','regular maintenance that prevents early failure','ignoring damage until it stops working','using it beyond every safety limit','regular maintenance that prevents early failure','及时维护可能延长设备使用寿命。'),Q('lifespan',4,2,'A battery with a short lifespan?','stops working after a relatively short period','lasts for the user’s entire life','cannot be replaced','stops working after a relatively short period','使用期限短说明它很快无法使用。')]});
D('lifestyle',{etymology:E('Lifestyle combines life and style; it describes the habits and way of living of a person or a group with shared patterns.','lifestyle'),contexts:[C('lifestyle.s2','社会学研究','The survey compared the lifestyle of seasonal farm workers with that of year-round residents in the same valley.','这项调查比较了同一山谷中季节性农场工人与常住居民的生活形态。','The survey compared the lifestyle of seasonal farm workers / with that of year-round residents / in the same valley.','lifestyle.s2 可指具有相似习惯或社会条件的群体共同生活形态。','调查比较两个群体的工作和居住模式。')],mistakes:[M('The study compared two lifestyles while examining no habits, routines, work patterns, or living conditions of either group.','The study compared the groups’ lifestyles by examining their work, food, and daily routines.','不考察任何生活习惯就无法比较生活方式。')],quiz:[Q('lifestyle',1,1,'A person’s lifestyle includes?','habits and the way they live','the length of their life only','a single rescue rope','habits and the way they live','lifestyle.s1 指个人生活方式。'),Q('lifestyle',2,2,'A group lifestyle may describe?','shared patterns of living among a community','one person’s legal debt','a lamp’s brightness','shared patterns of living among a community','lifestyle.s2 可描述群体共同的生活形态。'),Q('lifestyle',3,1,'Which detail tells us about someone’s lifestyle?','their routines for food, work, and rest','their name on a library card','the color of one shirt only','their routines for food, work, and rest','饮食、工作和休息习惯体现生活方式。'),Q('lifestyle',4,1,'Lifestyle combines life with?','style','span','saver','style','lifestyle 是 life 与 style 的复合词。','word-formation')]});
D('lifetime',{etymology:E('Lifetime combines life and time; it names the period during which a person is alive.','lifetime'),contexts:[C('lifetime.s1','人物传记','The scientist published more than sixty papers during her lifetime and mentored two generations of researchers.','这位科学家一生中发表了六十多篇论文，并指导了两代研究人员。','The scientist published more than sixty papers / during her lifetime / and mentored / two generations of researchers.','lifetime 指一个人从出生到死亡所经历的时间。','“during her lifetime”概括了她一生中的成就。')],mistakes:[M('The biography described a lifetime achievement as an event that occurred only after the person’s life had begun centuries later.','The biography described a lifetime achievement as work accomplished during the person’s life.','lifetime 指个人活着的那段时间。')],quiz:[Q('lifetime',1,1,'A lifetime is?','the period when a person is alive','one season of a year','the service life of a machine only','the period when a person is alive','lifetime.s1 指人的一生。'),Q('lifetime',2,1,'“She traveled widely in her lifetime” means she traveled?','while she was alive','only after she died','only during one afternoon','while she was alive','in her lifetime 指在她活着的时候。'),Q('lifetime',3,1,'Which phrase uses lifetime naturally?','a lifetime of careful research','a lifetime of one second','a lifetime from the pump only','a lifetime of careful research','“a lifetime of”可指一生积累的经历。'),Q('lifetime',4,1,'Lifetime combines life with?','time','line','light','time','该词由 life 和 time 组成。','word-formation')]});
D('lifeway',{etymology:E('Lifeway combines life and way; it is a less common noun for the customary manner or path of living followed by a person or community.','lifeway'),contexts:[C('lifeway.s1','人类学研究','The study documents the community’s lifeway, including seasonal travel, shared fishing practices, and ceremonies.','这项研究记录了该社区的生活方式，包括季节性迁徙、共同捕鱼习俗和仪式。','The study documents the community’s lifeway / including seasonal travel / shared fishing practices / and ceremonies.','lifeway 指个人或社区惯常的生活方式与生活道路，使用频率低于 lifestyle。','迁徙、捕鱼与仪式共同构成社区生活方式。')],mistakes:[M('The report described a lifeway while recording no customs, practices, daily routines, or community traditions.','The report described a lifeway by documenting the community’s customary practices and seasonal routines.','完全没有记录生活习惯，不能说明其 lifeway。')],quiz:[Q('lifeway',1,1,'A community’s lifeway is?','its customary manner of living','its average biological lifespan','a rescue rope','its customary manner of living','lifeway 指社区惯常的生活方式。'),Q('lifeway',2,1,'Which detail might describe a lifeway?','shared seasonal work and community ceremonies','the wattage of a single lamp','the legal status of one invoice','shared seasonal work and community ceremonies','共同习俗和季节性活动体现社区生活方式。'),Q('lifeway',3,1,'Lifeway is closest in meaning to?','way of life','life-size','lifelessness','way of life','way of life 与 lifeway 意义相近。','confusable'),Q('lifeway',4,1,'Lifeway is a relatively?','uncommon noun','common verb for turning on a lamp','legal title for a deputy','uncommon noun','lifeway 是较少见的名词。','register')]});
D('lift',{etymology:E('Lift comes from Old Norse lypta “to raise”; it can mean raise something, clear away or remove something, improve someone’s mood, use an elevator, or give someone a ride.','lift'),contexts:[C('lift.s4','英国出行','She took the lift to the sixth floor because the stairs were closed during repairs.','楼梯维修关闭期间，她乘电梯去了六楼。','She took the lift / to the sixth floor / because the stairs / were closed during repairs.','lift.s4 在英式英语中指在楼内上下运送人的电梯。','她乘坐设备前往高层。')],mistakes:[M('She took the lift to the sixth floor by walking up the stairs because the building had no vertical transport machine.','She took the lift to the sixth floor in the building’s elevator.','步行楼梯不是乘坐电梯。')],quiz:[Q('lift',1,1,'To lift a box is to?','raise it upward','make it heavier by adding cargo','write a legal claim','raise it upward','lift.s1 指举起或抬高。'),Q('lift',2,2,'When fog lifts, it?','clears or disappears','becomes a legal debt','raises a box','clears or disappears','lift.s2 可指雾消散，也可指解除规定。'),Q('lift',3,3,'A kind word may lift someone’s spirits by?','making them feel happier or more hopeful','making them less visible','causing a lien','making them feel happier or more hopeful','lift.s3 可指鼓舞情绪。'),Q('lift',4,5,'If a colleague gives you a lift, the colleague gives you?','a free ride in a vehicle','an elevator ticket only','a lifeline rope','a free ride in a vehicle','lift.s5 可指搭便车或免费乘车。')]});
D('liftoff',{etymology:E('Liftoff combines lift and off; it names the moment a rocket or spacecraft leaves the ground and begins flight.','liftoff'),contexts:[C('liftoff.s1','航天发射','At liftoff, the engines pushed the capsule upward as a bright plume spread beneath the launch vehicle.','发射升空时，发动机推动飞船上升，运载火箭下方展开明亮的尾焰。','At liftoff / the engines pushed the capsule upward / as a bright plume / spread beneath the launch vehicle.','liftoff 指火箭或航天器离开地面开始飞行的时刻。','飞船刚离开发射台，发动机正在推进。')],mistakes:[M('The launch report recorded liftoff while the rocket remained secured on the pad and never left the ground.','The launch report recorded liftoff when the rocket cleared the launch pad.','仍固定在发射台上没有离地，不是 liftoff。')],quiz:[Q('liftoff',1,1,'Liftoff is the moment when a rocket?','leaves the ground','lands on the runway','enters a library','leaves the ground','liftoff 指火箭发射升空。'),Q('liftoff',2,1,'What follows a successful liftoff?','the vehicle begins its ascent','the rocket is still bolted to the pad','a ship turns landward','the vehicle begins its ascent','离地后航天器开始上升。'),Q('liftoff',3,1,'Liftoff is a?','noun for the start of a flight','verb meaning to write a lexicon','term for a license','noun for the start of a flight','liftoff 是表示起飞时刻的名词。','word-formation'),Q('liftoff',4,1,'Which event is liftoff?','the launch vehicle rises clear of its pad','the crew prepares a launch checklist','the capsule returns to Earth','the launch vehicle rises clear of its pad','飞行器离开发射台是升空。')]});
D('ligament',{etymology:E('Ligament comes from Latin ligamentum, from ligare “to bind”; it names strong connective tissue that joins bones at a joint.','ligament'),contexts:[C('ligament.s1','运动医学','The scan showed a torn knee ligament, so the athlete began rehabilitation before returning to competition.','影像检查显示运动员膝部韧带撕裂，因此他在重返比赛前开始康复训练。','The scan showed a torn knee ligament / so the athlete began rehabilitation / before returning / to competition.','ligament 指连接关节处骨骼的坚韧结缔组织。','膝部韧带受伤后需要康复再恢复运动。')],mistakes:[M('The clinician called a muscle running from shoulder to elbow a ligament even though it contracted to move the arm rather than joining bones at a joint.','The clinician identified the tissue joining the knee bones as a ligament.','使肌肉收缩并移动手臂的组织不是连接骨骼的韧带。')],quiz:[Q('ligament',1,1,'A ligament connects?','bones at a joint','two dictionary entries','a lamp to a wall','bones at a joint','ligament 指关节处连接骨骼的组织。'),Q('ligament',2,1,'A torn ligament may require?','medical rehabilitation','a tax levy','a new lampshade','medical rehabilitation','韧带受伤后常需康复治疗。'),Q('ligament',3,1,'Ligament is a term from?','anatomy and medicine','lexicography','navigation only','anatomy and medicine','ligament 是解剖学术语。'),Q('ligament',4,1,'The root lig- in ligament is associated with?','binding','light','life','binding','拉丁语 ligare 意为“捆绑、连接”。','word-formation')]});
D('light',{etymology:E('Light has Old English roots for brightness and weightlessness, alongside a verb meaning kindle or illuminate; its senses include illumination, a lamp, lighting, and low weight or pale color.','light'),contexts:[C('light.s3','露营生火','They used a spark to light the camp stove before boiling water for tea.','他们用火花点燃露营炉，然后烧水泡茶。','They used a spark / to light the camp stove / before boiling water / for tea.','light.s3 作动词表示点燃火或火源。','火花点燃炉子，随后可加热水。'),C('light.s4','室内照明','The desk lamp lit the lower half of the page so Mara could read the small print.','台灯照亮了页面下半部，以便玛拉阅读小字。','The desk lamp lit the lower half of the page / so Mara could read / the small print.','light.s4 作动词表示照亮某处。','灯光使页面变亮可读。'),C('light.s5','登山装备','The climber packed a light jacket that added little weight to her full backpack.','登山者带了一件很轻的夹克，没有给装满物品的背包增加多少重量。','The climber packed a light jacket / that added little weight / to her full backpack.','light.s5 作形容词可表示重量轻，也可表示程度不重。','夹克不会明显增加背包重量。'),C('light.s6','室内装饰','They chose a light blue paint to make the narrow hallway appear brighter.','他们选择浅蓝色油漆，让狭窄的走廊看起来更明亮。','They chose a light blue paint / to make the narrow hallway / appear brighter.','light.s6 可表示颜色浅或明亮。','浅蓝色有助于使走廊显得更亮。')],mistakes:[M('The backpack felt light because its contents made it far heavier than the climber could carry.','The backpack felt light because it contained only a few lightweight items.','物品让背包变得极重，与 light 表示轻相反。')],quiz:[Q('light',1,1,'Light in a dark room means?','brightness that lets you see','a legal debt','a type of language','brightness that lets you see','light.s1 指使人能够看见的光线。'),Q('light',2,2,'A porch light is?','a device that produces brightness','a pale color only','a fire that has not been lit','a device that produces brightness','light.s2 指灯或光源设备。'),Q('light',3,3,'To light a candle is to?','make it start burning','make it weigh less','make it pale in color','make it start burning','light.s3 指点燃蜡烛。'),Q('light',4,5,'A light backpack is?','not weighing much','dark in color','full of heavy stones','not weighing much','light.s5 表示重量轻。')]});
D('light up',{etymology:E('Light up is a phrasal verb formed from light and up; it means make something bright or switch on a light.','light up'),contexts:[C('light up.s1','舞台照明','The technician will light up the backdrop when the final scene begins.','最后一幕开始时，技术员会点亮舞台背景。','The technician will light up the backdrop / when the final scene / begins.','light up 指使某物变亮或打开照明设备。','舞台背景在场景开始时被照亮。')],mistakes:[M('The technician lit up the stage by switching off every lamp and leaving the backdrop in darkness.','The technician lit up the stage by turning on the spotlights.','关掉所有灯会使舞台变暗而不是点亮。')],quiz:[Q('light up',1,1,'To light up a room is to?','make it bright or switch on its lights','make it heavier','remove a legal permit','make it bright or switch on its lights','light up 指点亮或照亮。'),Q('light up',2,1,'Which action lights up a theater?','turning on the stage lights','closing every curtain and switching off lamps','removing the seating','turning on the stage lights','开启舞台灯使剧院变亮。'),Q('light up',3,1,'The lantern lit up the path means it?','made the path bright enough to see','made the path longer','made the path disappear','made the path bright enough to see','灯笼照亮了道路。'),Q('light up',4,1,'Light up is a?','phrasal verb','noun for a debt','formal rank','phrasal verb','light up 由动词和小品词组成。','word-formation')]});
D('light-headed',{etymology:E('Light-headed combines light and headed; it describes the faint or dizzy feeling of being about to lose balance or consciousness.','light-headed'),contexts:[C('light-headed.s1','健康状况','After standing quickly in the heat, Rosa felt light-headed and sat down until the dizziness passed.','在炎热天气中迅速站起后，罗莎感到头晕，便坐下等待眩晕消退。','After standing quickly in the heat / Rosa felt light-headed / and sat down / until the dizziness passed.','light-headed 指有些晕眩、仿佛快要跌倒或昏厥的感觉。','突然站起后出现眩晕，坐下等待症状缓解。')],mistakes:[M('He felt light-headed but remained perfectly steady, alert, and free of any faint or dizzy sensation.','He felt light-headed and had to sit down because he was dizzy.','完全没有眩晕感，与 light-headed 的意思相反。')],quiz:[Q('light-headed',1,1,'Someone who feels light-headed feels?','slightly faint or dizzy','hungry for a full meal','unable to read a dictionary','slightly faint or dizzy','light-headed 指头晕或轻微眩晕。'),Q('light-headed',2,1,'Which situation might make someone light-headed?','standing up quickly after being ill','sitting calmly in a comfortable chair','reading a clear road sign','standing up quickly after being ill','突然站起可能引起短暂头晕。'),Q('light-headed',3,1,'A light-headed person may need to?','sit down until the dizziness passes','run faster immediately','operate a crane','sit down until the dizziness passes','坐下有助于避免眩晕时失去平衡。'),Q('light-headed',4,1,'Light-headed is an adjective describing?','a physical sensation','a legal permission','a coastal tower','a physical sensation','该词描述身体感觉。')]});
D('lighten',{etymology:E('Lighten is formed from light with -en; it can mean reduce weight or emotional burden, or make something brighter.','lighten'),contexts:[C('lighten.s1','行李整理','Removing the spare books helped lighten her suitcase before the long walk to the station.','去掉备用书籍后，她的手提箱轻了些，便于长途步行去车站。','Removing the spare books / helped lighten her suitcase / before the long walk / to the station.','lighten.s1 表示减轻物体重量，也可减轻担忧或气氛。','取出书本减少了行李重量。')],mistakes:[M('The traveler lightened the suitcase by adding two heavy books and a full metal toolbox.','The traveler lightened the suitcase by removing unnecessary books and tools.','增加重物不会减轻行李。')],quiz:[Q('lighten',1,1,'To lighten a bag is to?','reduce its weight','make it heavier','place it in a library','reduce its weight','lighten.s1 指减轻重量。'),Q('lighten',2,2,'The sky begins to lighten when it?','becomes brighter','grows darker','produces a lien','becomes brighter','lighten.s2 可指天色变亮。'),Q('lighten',3,1,'A joke may lighten the mood by?','making the atmosphere less serious','making a bag heavier','issuing a license','making the atmosphere less serious','玩笑可缓和气氛。'),Q('lighten',4,2,'Which change lightens a dark room?','opening the curtains to let in sunlight','covering every window','switching off all lights','opening the curtains to let in sunlight','让自然光进入可使房间变亮。')]});
D('lighter',{etymology:E('Lighter is formed from light with the agent or instrument ending -er; it names a small device that produces a flame for lighting cigarettes, candles, or fires.','lighter'),contexts:[C('lighter.s1','野外准备','The camper checked that the lighter still worked before packing it with the first-aid kit and matches.','露营者在把打火机与急救包和火柴一起装好前，先检查它是否还能使用。','The camper checked / that the lighter still worked / before packing it / with the first-aid kit and matches.','lighter 指用来产生火焰、点燃香烟或蜡烛的小型装置。','露营者检查设备能否点火。')],mistakes:[M('The lighter produced no flame because it was only a heavy metal bar used to lift a stone.','The lighter produced a flame that the camper used to start the stove.','仅用于撬石的金属杆不是点火装置。')],quiz:[Q('lighter',1,1,'A pocket lighter is used to?','produce a small flame','measure a person’s lifespan','read a lexicon','produce a small flame','lighter.s1 指打火机。'),Q('lighter',2,1,'Which object is a lighter?','a refillable device that sparks a flame','a lamp’s paper cover','a rope used to rescue swimmers','a refillable device that sparks a flame','能产生火焰的可填充装置是打火机。'),Q('lighter',3,1,'Someone may carry a lighter to light?','a candle','a dictionary entry','a landform','a candle','打火机可用于点燃蜡烛。'),Q('lighter',4,1,'A lighter differs from a lamp because it primarily?','creates a flame for ignition','provides steady room illumination','covers a bulb','creates a flame for ignition','lighter 用于点火，与照明灯不同。','distinction')]});
D('lighthearted',{etymology:E('Lighthearted combines light and hearted; it describes a cheerful, carefree mood or an amusing tone that is not solemn.','lighthearted'),contexts:[C('lighthearted.s1','团队活动','The coach ended the season with a lighthearted quiz that let the players laugh together after a demanding year.','赛季结束时，教练用一场轻松的问答让队员们在艰苦的一年后一起欢笑。','The coach ended the season / with a lighthearted quiz / that let the players laugh together / after a demanding year.','lighthearted 指轻松愉快、无忧无虑或不严肃的。','问答活动让疲惫的队员放松并开怀。')],mistakes:[M('The memorial speech was lighthearted because it discussed only grief in a solemn tone and included no cheerful or amusing note.','The closing reception was lighthearted, with gentle jokes and stories that helped guests relax.','全程庄重悲痛、没有轻松元素，不符合 lighthearted。')],quiz:[Q('lighthearted',1,1,'A lighthearted conversation is?','cheerful and relaxed','solemn and deeply mournful','legally binding','cheerful and relaxed','lighthearted 指轻松愉快的。'),Q('lighthearted',2,1,'Which event is lighthearted?','a friendly quiz with jokes after a hard season','a funeral service focused on grief','a serious court hearing','a friendly quiz with jokes after a hard season','轻松问答和玩笑具有轻快氛围。'),Q('lighthearted',3,1,'Lighthearted is closest to?','carefree','lifeless','liable','carefree','carefree 与 lighthearted 意思接近。','confusable'),Q('lighthearted',4,1,'A lighthearted tone would usually avoid?','excessive solemnity','gentle humor','cheerful stories','excessive solemnity','lighthearted 的语气通常不庄严沉重。')]});
D('lighthouse',{etymology:E('Lighthouse combines light and house; it names a coastal tower whose light guides ships and warns them of hazards.','lighthouse'),contexts:[C('lighthouse.s1','海上导航','The lighthouse flashed twice in the fog, marking the safe entrance to the harbor between the rocks.','灯塔在雾中闪了两次，标示出岩石之间通往港口的安全入口。','The lighthouse flashed twice in the fog / marking the safe entrance / to the harbor / between the rocks.','lighthouse 指海岸塔楼，利用灯光警示船只并标记港口入口。','闪光引导船只避开岩石并进入港口。')],mistakes:[M('The lighthouse warned ships by extinguishing its light and giving no signal near the dangerous rocks.','The lighthouse warned ships by flashing its beam near the hazardous coast.','不发光且没有信号，无法发挥灯塔导航作用。')],quiz:[Q('lighthouse',1,1,'A lighthouse helps ships by?','warning them of hazards and marking a harbor','measuring an aircraft’s liftoff','holding a collection of books','warning them of hazards and marking a harbor','lighthouse 指海岸导航灯塔。'),Q('lighthouse',2,1,'Where is a lighthouse most likely built?','on a coast near rocks or a harbor','inside a dry inland library','at the top of a staircase','on a coast near rocks or a harbor','灯塔通常位于海岸危险区域或港口附近。'),Q('lighthouse',3,1,'The light from a lighthouse can?','guide vessels through darkness or fog','make ships heavier','collect a tax','guide vessels through darkness or fog','灯光帮助船舶辨认航道。'),Q('lighthouse',4,1,'Lighthouse combines light with?','house','lifespan','ligament','house','lighthouse 由 light 与 house 构成。','word-formation')]});
D('lightly',{etymology:E('Lightly is the adverb from light; it can mean with little force or amount, or without serious thought or concern.','lightly'),contexts:[C('lightly.s2','风险决策','The board did not take the safety complaint lightly and ordered an independent inspection before reopening the site.','董事会没有轻视安全投诉，而是在重新开放场地前安排了独立检查。','The board did not take the safety complaint lightly / and ordered an independent inspection / before reopening the site.','lightly.s2 在 take something lightly 中表示不认真对待或轻视。','董事会认真处理投诉并安排检查。')],mistakes:[M('The committee took the safety warning lightly by closing the site immediately and commissioning a full independent inspection.','The committee took the safety warning lightly by dismissing it without any review.','立即关闭场地并全面检查是认真处理，不是轻视。')],quiz:[Q('lightly',1,1,'To touch something lightly is to touch it?','with little force','as hard as possible','only with a legal permit','with little force','lightly.s1 表示轻轻地。'),Q('lightly',2,2,'To take a warning lightly is to?','not treat it as serious','investigate it thoroughly','write it in a lexicon','not treat it as serious','lightly.s2 表示轻率或不认真地对待。'),Q('lightly',3,1,'Which person handles a glass lightly?','one who holds it gently','one who crushes it firmly','one who drops it deliberately','one who holds it gently','轻拿玻璃杯体现小力。'),Q('lightly',4,2,'“She did not take the accusation lightly” means she?','treated it seriously','laughed it off without concern','used a light-colored pen','treated it seriously','否定 take lightly 表示认真对待。','confusable')]});
D('lightness',{etymology:E('Lightness is formed from light with -ness; it can name low weight, a pale or bright quality, graceful ease, or an unserious manner.','lightness'),contexts:[C('lightness.s2','正式场合','The chair objected to the lightness of the remarks during a meeting called to discuss the fatal accident.','主席反对在讨论致命事故的会议上发表轻率言论。','The chair objected to the lightness of the remarks / during a meeting / called to discuss / the fatal accident.','lightness.s2 指不够严肃、可能不合时宜的轻率态度。','事故严重，轻率发言显得不合场合。')],mistakes:[M('The chair criticized the remarks for lightness even though they were grave, solemn, and carefully respectful.','The chair criticized the remarks for lightness because they joked about the fatal accident.','庄重尊重的发言并不轻率。')],quiz:[Q('lightness',1,1,'The lightness of a suitcase means?','the fact that it weighs little','the fact that it is legally owned','the fact that it contains a library','the fact that it weighs little','lightness.s1 可指重量轻。'),Q('lightness',2,1,'The lightness of a pale fabric refers to?','its pale or bright quality','its heavy weight','its legal status','its pale or bright quality','lightness.s1 也可指颜色浅或明亮。'),Q('lightness',3,2,'Lightness in a serious speech may mean?','an unsuitable lack of seriousness','a graceful pale color','a low physical weight','an unsuitable lack of seriousness','lightness.s2 指轻率。'),Q('lightness',4,1,'A dancer’s lightness of movement suggests?','graceful ease','a legal claim','a lack of life','graceful ease','lightness 也可描写动作轻盈。')]});
D('lightning',{etymology:E('Lightning comes from Old English lihting, related to light; it names the electrical flash in a storm and also appears adjectivally to mean extremely fast.','lightning'),contexts:[C('lightning.s1','雷暴天气','A bolt of lightning split the clouds, followed several seconds later by a deep roll of thunder.','一道闪电划破云层，几秒钟后传来低沉的雷声。','A bolt of lightning split the clouds / followed several seconds later / by a deep roll / of thunder.','lightning.s1 指雷暴期间天空中突然出现的明亮电光。','电光先出现，之后才听到雷声。')],mistakes:[M('The forecast described a lightning flash during the storm even though the sky remained clear and no electrical discharge occurred.','The forecast described a lightning flash that illuminated the clouds during the storm.','晴空中没有放电，就没有闪电。')],quiz:[Q('lightning',1,1,'Lightning is?','a sudden electrical flash in the sky','a tower guiding ships','a strong band joining bones','a sudden electrical flash in the sky','lightning.s1 指雷暴中的闪电。'),Q('lightning',2,2,'A lightning-fast response is?','extremely quick','very slow','legally restricted','extremely quick','lightning.s2 作形容词比喻极快。'),Q('lightning',3,1,'During a storm, lightning is often followed by?','thunder','a library catalog','a lifeline','thunder','闪电之后常听见雷声。'),Q('lightning',4,2,'A lightning turnaround happened?','extremely quickly','after several decades','only when the building was lit','extremely quickly','lightning-fast 表示速度极快。')]});
D('lightweight',{etymology:E('Lightweight combines light and weight; it describes something low in weight, something unimportant, or a competitor in a lighter weight class.','lightweight'),contexts:[C('lightweight.s1','登山装备','The lightweight stove weighed less than a mug and fit easily into the side pocket of the hiking pack.','这台轻便炉具比马克杯还轻，轻松放进了登山包侧袋。','The lightweight stove weighed less than a mug / and fit easily / into the side pocket / of the hiking pack.','lightweight.s1 指重量轻、易于携带的。','炉具质量小，适合随身携带。')],mistakes:[M('The expedition chose a lightweight stove even though it weighed more than the full pack and required two people to carry it.','The expedition chose a lightweight stove that added little weight to each hiker’s pack.','需要两人搬运的沉重炉具不是 lightweight。')],quiz:[Q('lightweight',1,1,'A lightweight backpack?','weighs little and is easy to carry','is made of very heavy stone','has no carrying straps','weighs little and is easy to carry','lightweight.s1 指重量轻。'),Q('lightweight',2,2,'A lightweight argument is?','unimportant or lacking influence','impossible to challenge','a legal claim on property','unimportant or lacking influence','lightweight.s2 比喻不重要或缺乏影响力。'),Q('lightweight',3,3,'A boxing lightweight is?','a competitor in a lighter weight class','a referee carrying no equipment','a person who writes a lexicon','a competitor in a lighter weight class','lightweight.s3 可指轻量级选手。'),Q('lightweight',4,1,'Which material helps make a lightweight case?','a thin low-density composite','a thick block of lead','a solid limestone slab','a thin low-density composite','低密度材料可减轻物品重量。')]});
D('like',{etymology:E('Like has separate Old English histories for “please” and “similar”; it can also express a polite wish, name something enjoyed, or introduce an informal comparison.','like'),contexts:[C('like.s3','外貌描写','The twins look like their grandmother, especially around the eyes and in the shape of their smiles.','这对双胞胎长得像祖母，尤其是眼睛周围和笑容的形状。','The twins look like their grandmother / especially around the eyes / and in the shape / of their smiles.','like.s3 作介词，表示相似或像某人、某物。','双胞胎与祖母有相似的面部特征。'),C('like.s4','个人偏好','One of her likes is quiet walking along the canal before work.','她的爱好之一是上班前沿运河安静地散步。','One of her likes / is quiet walking along the canal / before work.','like.s4 作名词，指某人喜欢的事物或活动。','散步是她喜欢做的事。'),C('like.s5','口语表达','Like I said, the last bus leaves at ten, so we should leave the concert before the encore.','就像我说的，末班车十点发车，所以我们应该在返场前离开音乐会。','Like I said / the last bus leaves at ten / so we should leave the concert / before the encore.','like.s5 在非正式口语中可作连词，表示“如同、正如”。','Like I said 引出前面已经说明过的内容。')],mistakes:[M('I would like a glass of water meant that I already enjoyed a glass I had never tasted and was not making a request.','I would like a glass of water is a polite way to ask for one.','would like 通常表达想要或礼貌请求，不表示已喜欢未尝过的东西。')],quiz:[Q('like',1,1,'To like a song is to?','find it pleasant or satisfying','ask for a legal permit','compare it with a lighthouse only','find it pleasant or satisfying','like.s1 作动词表示喜欢。'),Q('like',2,2,'“I would like some tea” is?','a polite way to say I want tea','a claim that tea resembles coffee','a list of favorite drinks','a polite way to say I want tea','would like 表示礼貌地想要。'),Q('like',3,3,'“Her voice is like her mother’s” means the voices are?','similar','unrelated','a legal liability','similar','like.s3 表示相似。'),Q('like',4,5,'In informal speech, “Like I told you, the store closes at six” means?','as I told you','I enjoy telling you','the store is a kind of library','as I told you','like 可在口语中引出“正如我说过的”。','usage')]});
D('likelihood',{etymology:E('Likelihood is formed from likely with -hood; it can mean the chance that an event will occur or, less commonly, prospects for future success.','likelihood'),contexts:[C('likelihood.s2','职业前景','After the failed first trial, the team still saw some likelihood of success because the revised design solved the main defect.','第一次试验失败后，团队仍认为有一定成功希望，因为修改后的设计解决了主要缺陷。','After the failed first trial / the team still saw some likelihood of success / because the revised design / solved the main defect.','likelihood.s2 可指希望或未来成功的前景。','改进设计后团队仍看见成功可能性。')],mistakes:[M('There was a strong likelihood of success even though the project had no funding, no working design, and no possible route forward.','There was little likelihood of success because the project lacked funding and a workable plan.','成功前景极差时，说“成功希望很大”不合事实。')],quiz:[Q('likelihood',1,1,'The likelihood of rain is?','the chance that rain will occur','the total amount of rain already collected','a legal permission to travel','the chance that rain will occur','likelihood.s1 指某事发生的可能性。'),Q('likelihood',2,2,'A team with a likelihood of future success has?','some prospect or hope of succeeding','no possible route to success','a guarantee that it will fail','some prospect or hope of succeeding','likelihood.s2 指成功前景或希望。'),Q('likelihood',3,1,'Which phrase is natural?','the likelihood of a delay','the likelihood for a delay','the likelihood by a delay','the likelihood of a delay','常见结构为 likelihood of something。','collocation'),Q('likelihood',4,1,'A high likelihood means an event is?','more probable','impossible','already forgotten','more probable','可能性高意味着更有可能发生。')]});
D('likely',{etymology:E('Likely comes from Old English geliclic, “similar or probable”; it means probably true or expected to happen and may function as an adjective or adverb.','likely'),contexts:[C('likely.s1','天气预报','The forecast says showers are likely in the afternoon, so the organizers moved the outdoor concert under a covered stage.','天气预报称下午很可能有阵雨，因此组织者把户外音乐会移到有顶棚的舞台下。','The forecast says showers are likely in the afternoon / so the organizers moved / the outdoor concert / under a covered stage.','likely 表示某事很可能发生或很可能为真。','预报的降雨可能性促使活动改换场地。')],mistakes:[M('Rain is likely this afternoon, so the forecast guarantees that not a single drop will fall.','Rain is likely this afternoon, so the forecast advises bringing an umbrella.','likely 表示可能而非绝对保证。')],quiz:[Q('likely',1,1,'If rain is likely, it is?','probably going to happen','certainly impossible','a type of legal claim','probably going to happen','likely 指很可能发生。'),Q('likely',2,1,'Which event is likely?','one supported by a strong forecast but not guaranteed','one that has been ruled out completely','one that is impossible by definition','one supported by a strong forecast but not guaranteed','可能性高仍不等于确定。'),Q('likely',3,1,'The most likely explanation is?','the one that probably best fits the facts','the one known to be impossible','the first idea with no evidence','the one that probably best fits the facts','likely 可形容较可能成立的解释。'),Q('likely',4,1,'Likely means?','probable','lifeless','limitless','probable','probable 与 likely 意思相近。','confusable')]});
D('liken',{etymology:E('Liken is formed from like with the verb suffix -en; it means describe or compare one thing as similar to another.','liken'),contexts:[C('liken.s1','科技评论','The reviewer likened the new battery to a small power station because it could run a laptop for several days.','评论者把新电池比作小型发电站，因为它能让笔记本电脑运行好几天。','The reviewer likened the new battery / to a small power station / because it could run a laptop / for several days.','liken 常用于 liken A to B，表示把A比作B。','评论者用小型发电站说明电池的供电能力。')],mistakes:[M('The reviewer likened the battery to a power station by insisting that the two objects had no feature or function in common.','The reviewer likened the battery to a power station because both could supply electricity.','声称毫无共同点与“作类比”矛盾。')],quiz:[Q('liken',1,1,'To liken one thing to another is to?','compare them as similar','say they are legally liable','place a lid on them','compare them as similar','liken 指把某物比作另一物。'),Q('liken',2,1,'Which sentence uses liken correctly?','She likened the city’s night lights to a field of stars.','She likened the city and said they were unrelated.','She likened the stars into a library.','She likened the city’s night lights to a field of stars.','liken 常用结构是 liken A to B。','collocation'),Q('liken',3,1,'An author may liken a difficult choice to?','a fork in the road','a verified dictionary entry','a simple lid','a fork in the road','道路岔口常被用来比喻选择。'),Q('liken',4,1,'Liken is closest in meaning to?','compare','limit','libel','compare','compare 是 liken 的近义词。','confusable')]});
D('likeness',{etymology:E('Likeness is formed from like with -ness; it means resemblance or an image that represents someone accurately.','likeness'),contexts:[C('likeness.s1','肖像评估','The portrait captured the actor’s likeness so well that several visitors recognized him before reading the label.','这幅肖像把演员画得惟妙惟肖，几位游客还没看标签就认出了他。','The portrait captured the actor’s likeness / so well / that several visitors recognized him / before reading the label.','likeness 指相似之处，也可指能准确表现某人的画像。','肖像准确呈现了演员的面貌。')],mistakes:[M('The portrait bore no likeness to its subject even though every viewer recognized the person immediately.','The portrait bore a strong likeness to its subject, whom viewers recognized at once.','人人立即认出主题人物，说明肖像具有明显相似性。')],quiz:[Q('likeness',1,1,'A likeness of a person is?','an image that resembles them','a legal debt','a type of weather flash','an image that resembles them','likeness 可指相貌逼真的画像。'),Q('likeness',2,1,'The likeness between two faces is their?','resemblance','difference in legal status','shared lifespan','resemblance','likeness.s1 也指相像或相似。'),Q('likeness',3,1,'Which portrait has a strong likeness?','one whose subject is readily recognizable','one showing a completely different face','one with no visible features','one whose subject is readily recognizable','肖像能让人认出对象，说明画得像。'),Q('likeness',4,1,'Likeness is formed from?','like','likely','lily','like','likeness 由 like 加 -ness 构成。','word-formation')]});
D('likewise',{etymology:E('Likewise combines like and wise, an older word for manner; it means in a similar way or, as a reply, the same to you.','likewise'),contexts:[C('likewise.s2','礼貌回应','“It was good to meet you,” said Arun. “Likewise,” replied Mei as they exchanged cards.','阿伦说：“很高兴见到你。”梅一边交换名片一边回答：“我也是。”','“It was good to meet you,” said Arun / “Likewise,” replied Mei / as they exchanged cards.','likewise.s2 可作简短回应，表示“我也一样”。','梅用 likewise 表示自己同样很高兴。')],mistakes:[M('When her colleague wished her a safe trip, she replied likewise to mean she hoped he would have an unsafe trip too.','When her colleague wished her a safe trip, she replied likewise to return the same good wish.','likewise 表示同样回祝，不是反向诅咒。')],quiz:[Q('likewise',1,1,'To act likewise is to act?','in a similar way','in a legally binding way','without life','in a similar way','likewise.s1 指同样地、照样。'),Q('likewise',2,2,'If someone says “Have a good evening,” replying “Likewise” means?','I wish the same to you','I disagree with you','I have a different evening','I wish the same to you','likewise.s2 可表示“你也一样”。'),Q('likewise',3,1,'Which sentence uses likewise to mean similarly?','The first team trained outdoors; the second did likewise.','The first team trained; likewise means a tax.','The team did nothing and likewise left.','The first team trained outdoors; the second did likewise.','第二队照样训练，表示以类似方式行动。'),Q('likewise',4,2,'A polite short reply to “Nice to meet you” is?','Likewise.','Limitless.','Lifeless.','Likewise.','likewise 可用于礼貌地回应相同感受。','usage')]});
D('liking',{etymology:E('Liking is formed from like with -ing and names a feeling of enjoyment or preference for someone or something.','liking'),contexts:[C('liking.s1','兴趣爱好','Her liking for botanical gardens began when she was a child and has continued through every move.','她从小就喜欢植物园，这种喜好在每次搬家后都延续了下来。','Her liking for botanical gardens began / when she was a child / and has continued / through every move.','liking 指对某人或某事物感到喜欢、享受的情绪。','她长期喜欢参观植物园。')],mistakes:[M('He had a strong liking for jazz even though he disliked every song and avoided every performance.','He had a strong liking for jazz and often attended local concerts.','持续厌恶且回避演出与“喜欢爵士”相矛盾。')],quiz:[Q('liking',1,1,'A liking for music is?','enjoyment or preference for music','a legal claim on a house','a person’s expected lifespan','enjoyment or preference for music','liking 指喜好。'),Q('liking',2,1,'Which person has a liking for lilies?','someone who enjoys growing and viewing them','someone who avoids them because of an allergy','someone who has never heard of flowers','someone who enjoys growing and viewing them','喜欢种植和观赏百合体现喜好。'),Q('liking',3,1,'The noun liking is related to the verb?','like','light','limit','like','liking 由 like 加 -ing 构成。','word-formation'),Q('liking',4,1,'“The job was not to her liking” means it?','did not suit her preferences','was exactly her favorite','belonged to her library','did not suit her preferences','to one’s liking 表示符合某人喜好。','usage')]});
D('lily',{etymology:E('Lily comes through Latin lilium from Greek leirion; it names a flowering plant and can also refer to certain water plants with similar flowers.','lily'),contexts:[C('lily.s2','池塘生态','A water lily spread flat leaves across the pond’s surface while its pale flower rose above them.','一株睡莲把扁平叶片铺在池塘表面，浅色花朵则高出水面。','A water lily spread flat leaves / across the pond’s surface / while its pale flower / rose above them.','lily.s2 可指睡莲等叶片浮于水面的相似植物。','叶片漂浮、水面开花，符合睡莲特征。')],mistakes:[M('The gardener called a submerged seaweed strand a water lily even though it had no floating leaves or flower.','The gardener called the pond plant with floating leaves and a surface flower a water lily.','没有浮叶或花的海藻不是睡莲。')],quiz:[Q('lily',1,1,'A garden lily is a?','flowering plant with large showy flowers','small metal lifting fitting','legal claim on property','flowering plant with large showy flowers','lily.s1 指百合类开花植物。'),Q('lily',2,2,'A water lily typically has?','flat leaves and flowers on the water surface','roots that grow only in dry air','a flame used to light a candle','flat leaves and flowers on the water surface','lily.s2 指睡莲等水生植物。'),Q('lily',3,2,'Which plant is a water lily?','one with floating leaves and an open pond flower','a terrestrial cactus in a dry pot','a tree branch','one with floating leaves and an open pond flower','漂浮叶片和水面花朵是睡莲特征。'),Q('lily',4,1,'A bouquet of lilies contains?','flowering plants','computer programs','small lamps','flowering plants','百合属于花卉。')]});
D('limb',{etymology:E('Limb comes from Old English lim; it can mean an arm, leg, or wing of an animal, or a large branch of a tree.','limb'),contexts:[C('limb.s2','树木修剪','A heavy limb broke from the oak during the storm and blocked the garden path.','暴风雨中，一根粗大的橡树枝折断，挡住了花园小路。','A heavy limb broke from the oak / during the storm / and blocked / the garden path.','limb.s2 指树木粗大的枝干。','折断的粗枝落到路上。')],mistakes:[M('The gardener called a tiny leaf a limb even though it was not a large branch or a body part.','The gardener called the thick branch extending from the trunk a limb.','小叶片既非身体肢体，也不是大树枝。')],quiz:[Q('limb',1,1,'A human limb is an?','arm or leg','eyelid','organism without life','arm or leg','limb.s1 指手臂或腿等肢体。'),Q('limb',2,2,'A tree limb is?','a large branch','a small flower petal','a legal license','a large branch','limb.s2 指大树枝。'),Q('limb',3,1,'Which injury affects a limb?','a broken arm','a cracked lampshade','a lien on property','a broken arm','手臂骨折属于肢体受伤。'),Q('limb',4,2,'A thick branch that grows from a trunk can be called a?','limb','lapse','liking','limb','树干长出的粗枝可称 limb。')]});
D('lime',{etymology:E('Lime has separate senses: the citrus fruit entered English through European forms linked to Persian limu, while lime for calcium material comes from Latin calx; the color name comes from the fruit.','lime'),contexts:[C('lime.s2','建筑材料','The mason mixed lime with sand and water to prepare mortar for repairing the old stone wall.','石匠把石灰与沙子和水混合，制成修复旧石墙的砂浆。','The mason mixed lime with sand and water / to prepare mortar / for repairing / the old stone wall.','lime.s2 指由石灰岩制成、用于砂浆或土壤改良的石灰材料。','石灰作为砂浆成分用于砌筑修补。')],mistakes:[M('The mason used lime mortar by replacing the calcium-based lime with sour green citrus juice.','The mason used mineral lime mixed with sand and water to make mortar.','青柠果汁不是建筑砂浆中的石灰材料。')],quiz:[Q('lime',1,1,'A lime in a fruit bowl is?','a small sour green citrus fruit','a white building powder','a tree branch','a small sour green citrus fruit','lime.s1 指青柠或酸橙。'),Q('lime',2,2,'A builder may use lime to make?','mortar','a fruit salad only','a water lily','mortar','lime.s2 指石灰材料，可用于砂浆。'),Q('lime',3,3,'Lime-colored fabric is?','bright yellow-green','dark blue','pale gray','bright yellow-green','lime.s3 指鲜亮的黄绿色。'),Q('lime',4,2,'Which bag contains building lime?','a sack of calcium-based powder for mortar','a bag of green citrus fruit','a jar of lamp oil','a sack of calcium-based powder for mortar','建筑石灰是矿物粉末而非水果。')]});
D('limelight',{etymology:E('Limelight originally named an intense stage light produced by heating quicklime; figuratively it means the focus of public attention.','limelight'),contexts:[C('limelight.s1','公众人物','The young scientist found herself in the limelight after her discovery was featured in national news.','这位年轻科学家的发现登上全国新闻后，她成了公众关注的焦点。','The young scientist found herself in the limelight / after her discovery / was featured / in national news.','limelight.s1 比喻公众注意力的中心。','全国报道使科学家受到广泛关注。')],mistakes:[M('The actor avoided the limelight by giving interviews every day and placing his name on every headline.','The actor avoided the limelight by declining publicity and keeping a low profile.','频繁接受采访会让人处于公众关注中心。')],quiz:[Q('limelight',1,1,'To be in the limelight is to be?','the focus of public attention','hidden from every observer','a person’s legal liability','the focus of public attention','limelight.s1 指公众关注的中心。'),Q('limelight',2,2,'The original limelight was?','a very bright stage lamp using heated lime','a water lily in a pond','a type of computer library','a very bright stage lamp using heated lime','limelight.s2 指历史上的石灰光舞台灯。'),Q('limelight',3,1,'Which event puts a researcher in the limelight?','a widely reported discovery','a private routine lab meeting','a canceled appointment nobody knows about','a widely reported discovery','广泛报道会让研究者受到公众关注。'),Q('limelight',4,1,'Someone avoiding the limelight wants to avoid?','public attention','a lamp’s electricity','a citrus fruit','public attention','limelight 的比喻义是公众瞩目。')]});
D('limestone',{etymology:E('Limestone combines lime and stone; it is a sedimentary rock rich in calcium carbonate, used in buildings and cement production.','limestone'),contexts:[C('limestone.s1','地质考察','The cave formed as slightly acidic groundwater slowly dissolved the limestone beneath the hillside.','微酸地下水慢慢溶解山坡下的石灰岩，形成了这座洞穴。','The cave formed / as slightly acidic groundwater / slowly dissolved the limestone / beneath the hillside.','limestone 指富含碳酸钙、常用于建筑和水泥生产的沉积岩。','地下水溶蚀石灰岩可形成洞穴。')],mistakes:[M('The geologist identified the hard igneous basalt as limestone even though it contained no calcium carbonate.','The geologist identified the calcium-carbonate-rich pale rock as limestone.','不含碳酸钙的玄武岩不符合 limestone 特征。')],quiz:[Q('limestone',1,1,'Limestone is a type of?','sedimentary rock rich in calcium carbonate','soft fabric used for lace','metal fitting for hoisting','sedimentary rock rich in calcium carbonate','limestone 指富含碳酸钙的沉积岩。'),Q('limestone',2,1,'Limestone is often used to make?','cement and building materials','a programming language','a lifesaver rope','cement and building materials','石灰岩常用于水泥和建筑。'),Q('limestone',3,1,'A cave may form in limestone when?','slightly acidic water dissolves the rock','the rock turns into a lily','a lamp heats the stone to a flame','slightly acidic water dissolves the rock','酸性地下水可逐渐溶解石灰岩形成洞穴。'),Q('limestone',4,1,'Limestone combines lime with?','stone','light','like','stone','limestone 由 lime 和 stone 构成。','word-formation')]});
D('limit',{etymology:E('Limit comes from Latin limes “boundary”; it can mean a maximum amount or boundary and, as a verb, restrict how far something can go.','limit'),contexts:[C('limit.s3','公共安全','The city will limit traffic on the bridge to one lane while engineers inspect the damaged support.','工程师检查受损支撑期间，市政府将把桥上交通限制为单车道。','The city will limit traffic on the bridge / to one lane / while engineers inspect / the damaged support.','limit.s3 作动词，表示把某事控制在规定范围内。','车辆通行被限制在一条车道。')],mistakes:[M('The city limited the bridge traffic by opening every lane and removing all restrictions during inspection.','The city limited the bridge traffic by closing two lanes and allowing only one through.','开放所有车道是放宽而不是限制交通。')],quiz:[Q('limit',1,1,'A speed limit is?','the greatest permitted speed','the exact weight of a car','a road’s lighting device','the greatest permitted speed','limit.s1 指最大允许值。'),Q('limit',2,2,'The limits of a park are?','its boundaries','its public library collection','its lifespan','its boundaries','limit.s2 可指区域边界。'),Q('limit',3,3,'To limit the number of visitors is to?','set a maximum they may not exceed','invite everyone without restriction','make the park limitless','set a maximum they may not exceed','limit.s3 作动词表示设上限。'),Q('limit',4,1,'Which sign states a limit?','maximum occupancy: 40','open to any number of people','no stated maximum','maximum occupancy: 40','标明最大人数就设定了限额。')]});
D('limitation',{etymology:E('Limitation is formed from limit with -ation; it can mean a rule or condition restricting action or a weakness that reduces effectiveness.','limitation'),contexts:[C('limitation.s2','研究方法','A limitation of the study is that it included only urban clinics and may not represent rural patients.','这项研究的局限是只纳入城市诊所，因此可能无法代表农村患者。','A limitation of the study / is that it included only urban clinics / and may not represent / rural patients.','limitation.s2 指使人或事物效果降低的局限性或缺点。','样本范围有限，影响结论的普遍性。')],mistakes:[M('The researcher called the broad national sample a limitation even though it included every region and represented both rural and urban clinics.','The researcher noted that excluding rural clinics was a limitation of the sample.','样本覆盖全面不是此处的局限。')],quiz:[Q('limitation',1,1,'A limitation on access is?','a rule or condition restricting access','an unlimited permission','a public spotlight','a rule or condition restricting access','limitation.s1 指限制行为的规定或条件。'),Q('limitation',2,2,'A limitation of a study is?','a weakness that reduces how broadly its results apply','a guarantee that all results are correct','a type of lime','a weakness that reduces how broadly its results apply','limitation.s2 指研究局限性。'),Q('limitation',3,2,'Which is a limitation of a survey?','it includes too few rural participants to represent them','it accurately covers every intended group','it uses a clear questionnaire','it includes too few rural participants to represent them','样本缺少农村参与者会限制结果的适用范围。'),Q('limitation',4,1,'Limitation is related to the verb?','limit','liken','lighten','limit','limitation 由 limit 派生。','word-formation')]});
D('limitative',{etymology:E('Limitative is formed from limit with the adjective suffix -ative; it describes something that has the effect of setting or imposing a limit.','limitative'),contexts:[C('limitative.s1','制度分析','The rule is limitative because it caps the number of applications each household may submit.','这项规定具有限制作用，因为它限制了每户可以提交的申请数量。','The rule is limitative / because it caps the number of applications / each household / may submit.','limitative 描述会设定或施加限制的事物。','每户申请数量被设定上限。')],mistakes:[M('The policy was limitative even though it removed every cap and allowed unlimited applications from each household.','The policy was limitative because it imposed a fixed application cap on each household.','取消所有上限与限制作用相反。')],quiz:[Q('limitative',1,1,'A limitative rule?','sets or imposes a limit','removes every restriction','provides a lifeline','sets or imposes a limit','limitative 指具有限制作用的。'),Q('limitative',2,1,'Which rule is limitative?','one that caps each household at two applications','one that permits unlimited applications','one that removes all eligibility requirements','one that caps each household at two applications','申请上限体现限制作用。'),Q('limitative',3,1,'Limitative is the adjective related to?','limit','lily','likelihood','limit','limitative 由 limit 派生。','word-formation'),Q('limitative',4,1,'A limitative condition will?','restrict what can be done','make a light brighter','increase a lifespan','restrict what can be done','具有限制性的条件会缩小可做范围。')]});
D('limited',{etymology:E('Limited is the past participle of limit used as an adjective; it means restricted or not great in amount, number, or ability.','limited'),contexts:[C('limited.s1','资源规划','Because the clinic has limited vaccine supplies, staff are prioritizing patients at highest risk.','由于诊所的疫苗储备有限，工作人员优先安排风险最高的患者接种。','Because the clinic has limited vaccine supplies / staff are prioritizing / patients / at highest risk.','limited 表示数量或能力不多、受到限制的。','疫苗不足以满足所有需求，因此需要优先安排。')],mistakes:[M('The clinic had limited supplies even though it had more doses than every patient could use and an unlimited reserve.','The clinic had limited supplies because only a small number of doses remained.','储备充足且无限时，不应说数量有限。')],quiz:[Q('limited',1,1,'Limited funds are?','restricted or not very great in amount','unlimited and abundant','legally owed to a bank','restricted or not very great in amount','limited 指数量不多或有限的。'),Q('limited',2,1,'A person with limited experience has?','not much experience','more experience than anyone else','no possible future','not much experience','limited 也可指能力或经验有限。'),Q('limited',3,1,'Which resource is limited?','only three seats remain for twenty applicants','there are endless empty seats','every applicant already has a seat','only three seats remain for twenty applicants','座位少于申请人数，说明资源有限。'),Q('limited',4,1,'Limited is the adjective form related to?','limit','lien','languish','limit','limited 是 limit 的过去分词形容词。','word-formation')]});
D('limitless',{etymology:E('Limitless combines limit with the negative suffix -less; it means having no apparent boundary, end, or restriction.','limitless'),contexts:[C('limitless.s1','科幻想象','The novel imagines a limitless energy source that could power every city without fuel shortages.','这部小说设想了一种无穷无尽的能源，可以在没有燃料短缺的情况下为每座城市供电。','The novel imagines a limitless energy source / that could power every city / without fuel shortages.','limitless 表示似乎没有上限或尽头的。','能源不受数量上限或燃料短缺制约。')],mistakes:[M('The city had limitless water even though strict quotas stopped every household after one small bottle.','The city had limitless water because its reservoir could supply residents without a fixed cap.','每户只能领取一小瓶水，说明供应受严格限制。')],quiz:[Q('limitless',1,1,'Limitless opportunities are?','apparently without end or restriction','strictly capped at one','legally denied','apparently without end or restriction','limitless 指没有明显限制或尽头。'),Q('limitless',2,1,'Which resource seems limitless in a story?','an inexhaustible supply that never runs out','a tank with only one liter remaining','a ration strictly capped by law','an inexhaustible supply that never runs out','永不耗尽的供应似乎没有上限。'),Q('limitless',3,1,'The suffix -less in limitless means?','without','full of','likely to','without','-less 表示“没有”。','word-formation'),Q('limitless',4,1,'Limitless is the opposite of?','limited','lifelike','lighthearted','limited','limited 表示有限的，与 limitless 相反。','confusable')]});
D('limits',{etymology:E('Limits is the plural of limit; it names the boundaries or furthest points that define what is allowed or possible.','limits'),contexts:[C('limits.s1','团队协作','The team agreed on clear limits for after-hours messages so employees could disconnect from work.','团队为下班后的消息设定了明确界限，让员工可以暂时脱离工作。','The team agreed on clear limits / for after-hours messages / so employees could disconnect / from work.','limits 指规定允许或可能达到的边界，常用复数形式。','明确的界限规定了何时不再要求员工回复。')],mistakes:[M('The company set limits by telling workers there were no boundaries on working hours or after-hours messages.','The company set limits by specifying when employees were not expected to respond.','取消所有边界并非设定 limits。')],quiz:[Q('limits',1,1,'The limits of a field define?','the furthest points or boundaries it reaches','the number of flowers inside it only','a person’s entire lifetime','the furthest points or boundaries it reaches','limits.s1 指范围或界限。'),Q('limits',2,1,'“Know your limits” means know?','the boundaries of what you can safely or reasonably do','the names of every library book','how to repair a ligament','the boundaries of what you can safely or reasonably do','了解自己的能力或安全边界。'),Q('limits',3,1,'Which phrase uses limits correctly?','within the limits of the agreement','under the limits to the agreement','at limits of by agreement','within the limits of the agreement','within the limits of 是常见搭配。','collocation'),Q('limits',4,1,'A speed limit sets the?','maximum allowed speed','minimum vehicle lifespan','brightness of a light','maximum allowed speed','速度限制确定了允许的最大速度。')]});
D('limner',{etymology:E('Limner comes from Middle English limner, from limn “to paint or illuminate,” ultimately related to Latin illuminare; it names a painter, especially one who made small portraits.','limner'),contexts:[C('limner.s1','艺术史','The limner painted a small portrait of the merchant in delicate colors on a sheet of vellum.','这位画匠在一张羊皮纸上用细腻色彩为商人画了一幅小肖像。','The limner painted a small portrait / of the merchant / in delicate colors / on a sheet of vellum.','limner 指画家，历史上尤指绘制小型肖像画的画匠。','画家在羊皮纸上完成精细的小肖像。')],mistakes:[M('The museum called a person who only compiled word definitions a limner, although she never painted or drew.','The museum called the artist who painted miniature portraits a limner.','只编词典而不作画的人不是 limner。')],quiz:[Q('limner',1,1,'A limner is an artist who?','paints or draws, often small portraits','compiles a dictionary','repairs a lighthouse','paints or draws, often small portraits','limner 指画家或画匠，常作小肖像。'),Q('limner',2,1,'Which work might a historical limner create?','a carefully painted miniature portrait','a legal claim on property','a large limestone block','a carefully painted miniature portrait','细密小肖像是 limner 常见作品。'),Q('limner',3,1,'Limner is related to a verb meaning?','paint or illuminate','levy a tax','lie about a fact','paint or illuminate','limner 源自 limn，表示绘画或描绘。','word-formation'),Q('limner',4,1,'A limner differs from a lexicographer because a limner?','creates images rather than dictionary entries','writes definitions rather than portraits','issues licenses','creates images rather than dictionary entries','画匠创作图像，而词典编纂者编辑词条。','distinction')]});

})();
